-- ═════════ 001_core.sql ═════════
-- Mamar Booking · 001 core schema
-- The same file runs on Supabase (SQL editor) and locally in PGlite (mamar/dev/server.js).
-- Every statement is re-runnable.
--
-- Ground rules
--   · All money is integer halalas (1 SAR = 100).
--   · All instants are timestamptz; business-day clock times are minutes after local midnight in Asia/Riyadh.
--     Never write '+03' in SQL — always `at time zone 'Asia/Riyadh'`.
--   · Clients never touch tables. They call RPCs fn(p jsonb) returns jsonb:
--       pub_  anyone          own_  business members (and admins)
--       adm_  admins only     svc_  service role only (Edge Functions)
--     `_`-prefixed functions are internal and granted to nobody (see 999_grants.sql).

create schema if not exists extensions;
create extension if not exists btree_gist with schema extensions;

-- ───────────────────────── helpers ─────────────────────────

-- Raise a stable error code the clients translate (message = code, detail = optional json).
create or replace function public._err(code text, detail jsonb default null) returns void
language plpgsql as $$
begin
  raise exception using errcode = 'P0001', message = code, detail = coalesce(detail::text, '');
end $$;

-- Recursive jsonb merge: objects merge key by key, everything else is replaced by b.
create or replace function public._jmerge(a jsonb, b jsonb) returns jsonb
language sql immutable as $$
  select case
    when jsonb_typeof(a) = 'object' and jsonb_typeof(b) = 'object' then
      coalesce((select jsonb_object_agg(k,
                  case when a ? k and b ? k then public._jmerge(a -> k, b -> k)
                       when b ? k then b -> k else a -> k end)
                from (select jsonb_object_keys(a) k union select jsonb_object_keys(b)) keys), '{}'::jsonb)
    when b is null then a
    else b end
$$;

-- Short human-readable reference, e.g. MB-7K3QXR (no 0/O/1/I/L).
create or replace function public._ref(prefix text) returns text
language plpgsql volatile as $$
declare
  alphabet constant text := '23456789ABCDEFGHJKMNPQRSTUVWXYZ';
  bytes bytea := decode(replace(gen_random_uuid()::text, '-', ''), 'hex');
  r text := '';
begin
  for i in 0..5 loop
    r := r || substr(alphabet, (get_byte(bytes, i) % 31) + 1, 1);
  end loop;
  return prefix || '-' || r;
end $$;

-- 64 hex chars from two v4 uuids (244 random bits). Only its sha256 is stored.
create or replace function public._token() returns text
language sql volatile as $$
  select replace(gen_random_uuid()::text || gen_random_uuid()::text, '-', '')
$$;

create or replace function public._hash(t text) returns bytea
language sql immutable as $$ select sha256(convert_to(coalesce(t, ''), 'UTF8')) $$;

-- Phone → E.164. Saudi mobiles in any common spelling (Arabic-Indic digits too) → +9665XXXXXXXX.
-- Other international numbers must start with + or 00. Returns null when invalid.
create or replace function public._phone(raw text) returns text
language plpgsql immutable as $$
declare
  s text := translate(coalesce(raw, ''), '٠١٢٣٤٥٦٧٨٩۰۱۲۳۴۵۶۷۸۹', '01234567890123456789');
  intl boolean := btrim(s) like '+%' or btrim(s) like '00%';
  d text := regexp_replace(s, '[^0-9]', '', 'g');
begin
  if d like '00%' then d := substr(d, 3); end if;
  if d ~ '^9665[0-9]{8}$' then return '+' || d; end if;
  if d ~ '^05[0-9]{8}$' then return '+966' || substr(d, 2); end if;
  if d ~ '^5[0-9]{8}$' and not intl then return '+966' || d; end if;
  if intl and d ~ '^[1-9][0-9]{7,14}$' then return '+' || d; end if;
  return null;
end $$;

-- Riyadh wall clock → instant.
create or replace function public._at(d date, minutes integer) returns timestamptz
language sql immutable as $$
  select (d::timestamp + make_interval(mins => minutes)) at time zone 'Asia/Riyadh'
$$;

create or replace function public._today() returns date
language sql stable as $$ select (now() at time zone 'Asia/Riyadh')::date $$;

-- ───────────────────────── people ─────────────────────────

create table if not exists public.admins (
  user_id    uuid primary key references auth.users(id) on delete cascade,
  created_at timestamptz not null default now()
);

-- ───────────────────────── businesses ─────────────────────────

create table if not exists public.businesses (
  id            uuid primary key default gen_random_uuid(),
  slug          text not null unique check (slug ~ '^[a-z0-9][a-z0-9-]{1,38}[a-z0-9]$'),
  status        text not null default 'draft' check (status in ('draft','awaiting_payment','active','paused')),
  is_demo       boolean not null default false,
  kind          text not null default 'salon' check (kind in ('salon','carwash','activity','other')),
  name_ar       text not null default '',
  name_en       text not null default '',
  tagline_ar    text not null default '',
  tagline_en    text not null default '',
  phone         text,                       -- the shop's WhatsApp line, E.164
  address_ar    text not null default '',
  address_en    text not null default '',
  maps_url      text,
  site_url      text,
  instagram     text,
  lat           double precision,
  lng           double precision,
  city          text not null default 'jeddah',
  langs         text[] not null default '{ar}'
                check (langs <@ array['ar','en']::text[] and cardinality(langs) between 1 and 2),
  look          text not null default 'standard' check (look in ('standard','custom')),
  theme         jsonb not null default '{}',   -- {mode, accent, bg, ink, font, radius, logo_url}
  entitlements  jsonb not null default '{}',   -- what Ahmed sold; admin-only
  settings      jsonb not null default '{}',   -- what the owner may tune, within entitlements
  moyasar_pk    text,                          -- publishable key (public by design)
  request_id    uuid,
  setup_halalas integer,
  created_at    timestamptz not null default now(),
  updated_at    timestamptz not null default now()
);

-- Secret keys never leave the server: no grants, no policies, read only by svc_ functions.
create table if not exists public.business_secrets (
  business_id uuid primary key references public.businesses(id) on delete cascade,
  moyasar_sk  text,
  updated_at  timestamptz not null default now()
);

-- An extra branch is simply another business row with the same member.
create table if not exists public.members (
  business_id uuid not null references public.businesses(id) on delete cascade,
  user_id     uuid not null references auth.users(id) on delete cascade,
  role        text not null default 'owner' check (role in ('owner','staff')),
  created_at  timestamptz not null default now(),
  primary key (business_id, user_id)
);
create index if not exists members_user_idx on public.members(user_id);

create table if not exists public.sections (
  id          uuid primary key default gen_random_uuid(),
  business_id uuid not null references public.businesses(id) on delete cascade,
  name_ar     text not null default '',
  name_en     text not null default '',
  audience    text not null default 'all' check (audience in ('all','men','women')),
  sort        integer not null default 0
);
create index if not exists sections_business_idx on public.sections(business_id);

-- Weekly hours per section. A split shift is two rows; close_min > 1440 runs past midnight
-- (e.g. 16:00–02:00 = 960..1560) and belongs to the day it opened.
create table if not exists public.hours (
  id          bigint generated always as identity primary key,
  business_id uuid not null references public.businesses(id) on delete cascade,
  section_id  uuid not null references public.sections(id) on delete cascade,
  weekday     smallint not null check (weekday between 0 and 6),   -- 0 = Sunday (Postgres dow)
  open_min    integer not null check (open_min between 0 and 1439),
  close_min   integer not null check (close_min <= 2880),
  check (close_min > open_min)
);
create index if not exists hours_section_idx on public.hours(section_id, weekday);

-- Ramadan, Eid, holidays: replaces the weekly hours for every day in the range.
-- ranges = [[open_min, close_min], …]; [] = closed.
create table if not exists public.special_hours (
  id          uuid primary key default gen_random_uuid(),
  business_id uuid not null references public.businesses(id) on delete cascade,
  section_id  uuid references public.sections(id) on delete cascade,   -- null = every section
  from_date   date not null,
  to_date     date not null,
  ranges      jsonb not null default '[]',
  label_ar    text not null default '',
  label_en    text not null default '',
  check (to_date >= from_date)
);
create index if not exists special_hours_business_idx on public.special_hours(business_id, from_date);

-- Staff are labels the business chooses ("Chair 1"), never required to be names.
create table if not exists public.staff (
  id          uuid primary key default gen_random_uuid(),
  business_id uuid not null references public.businesses(id) on delete cascade,
  section_id  uuid references public.sections(id) on delete set null,  -- null = every section
  label_ar    text not null default '',
  label_en    text not null default '',
  services    uuid[],                                                  -- null = every staff-mode service
  active      boolean not null default true,
  sort        integer not null default 0
);
create index if not exists staff_business_idx on public.staff(business_id);

-- Parallel capacity: wash bays, karting seats. Shared by every service that points at it.
create table if not exists public.resources (
  id          uuid primary key default gen_random_uuid(),
  business_id uuid not null references public.businesses(id) on delete cascade,
  section_id  uuid references public.sections(id) on delete set null,
  label_ar    text not null default '',
  label_en    text not null default '',
  capacity    integer not null default 1 check (capacity between 1 and 500),
  active      boolean not null default true,
  sort        integer not null default 0
);
create index if not exists resources_business_idx on public.resources(business_id);

create table if not exists public.categories (
  id          uuid primary key default gen_random_uuid(),
  business_id uuid not null references public.businesses(id) on delete cascade,
  section_id  uuid references public.sections(id) on delete set null,
  name_ar     text not null default '',
  name_en     text not null default '',
  sort        integer not null default 0
);
create index if not exists categories_business_idx on public.categories(business_id);

create table if not exists public.services (
  id            uuid primary key default gen_random_uuid(),
  business_id   uuid not null references public.businesses(id) on delete cascade,
  section_id    uuid references public.sections(id) on delete set null,   -- null = every section
  category_id   uuid references public.categories(id) on delete set null,
  name_ar       text not null default '',
  name_en       text not null default '',
  desc_ar       text not null default '',
  desc_en       text not null default '',
  duration_min  integer not null default 30 check (duration_min between 5 and 720),
  buffer_min    integer not null default 0 check (buffer_min between 0 and 240),
  step_min      integer not null default 15 check (step_min between 5 and 240),
  mode          text not null default 'staff' check (mode in ('staff','capacity')),
  resource_id   uuid references public.resources(id) on delete set null,
  max_qty       integer not null default 1 check (max_qty between 1 and 50),
  per_person    boolean not null default false,       -- price × party size (karting heats)
  price_halalas integer not null default 0 check (price_halalas >= 0),
  price_from    boolean not null default false,       -- shown as "from 80 SAR"
  location      text not null default 'shop' check (location in ('shop','mobile','both')),
  active        boolean not null default true,
  sort          integer not null default 0,
  created_at    timestamptz not null default now(),
  check (mode = 'staff' or resource_id is not null)
);
create index if not exists services_business_idx on public.services(business_id, sort);

-- Offers apply to bookings made while the offer is live; weekdays (optional) restrict the
-- appointment day ("Sunday special"). kind 'banner' is a message only, no discount.
create table if not exists public.offers (
  id          uuid primary key default gen_random_uuid(),
  business_id uuid not null references public.businesses(id) on delete cascade,
  service_ids uuid[],                                  -- null = every service
  kind        text not null default 'percent' check (kind in ('percent','amount','banner')),
  value       integer not null default 0 check (value >= 0),   -- percent 1..90 or halalas
  title_ar    text not null default '',
  title_en    text not null default '',
  starts_at   timestamptz,
  ends_at     timestamptz,
  weekdays    smallint[],
  active      boolean not null default true,
  created_at  timestamptz not null default now(),
  check (kind <> 'percent' or value between 0 and 90)
);
create index if not exists offers_business_idx on public.offers(business_id);

-- Closed time. All target columns null = the whole business (or section).
create table if not exists public.blocks (
  id          uuid primary key default gen_random_uuid(),
  business_id uuid not null references public.businesses(id) on delete cascade,
  section_id  uuid references public.sections(id) on delete cascade,
  staff_id    uuid references public.staff(id) on delete cascade,
  resource_id uuid references public.resources(id) on delete cascade,
  during      tstzrange not null,
  reason      text not null default '',
  created_at  timestamptz not null default now()
);
create index if not exists blocks_business_idx on public.blocks using gist (business_id, during);

-- ───────────────────────── bookings ─────────────────────────

create table if not exists public.bookings (
  id               uuid primary key default gen_random_uuid(),
  ref              text not null unique,
  business_id      uuid not null references public.businesses(id) on delete cascade,
  section_id       uuid references public.sections(id) on delete set null,
  service_id       uuid references public.services(id) on delete set null,
  staff_id         uuid references public.staff(id) on delete set null,
  resource_id      uuid references public.resources(id) on delete set null,
  qty              integer not null default 1 check (qty between 1 and 100),
  starts_at        timestamptz not null,
  ends_at          timestamptz not null,
  busy             tstzrange not null,         -- [start, end + buffer + travel)
  status           text not null default 'confirmed'
                   check (status in ('pending_payment','confirmed','completed','no_show','cancelled','expired')),
  hold_until       timestamptz,
  name             text not null default '',
  phone            text,
  email            text,
  note             text,
  location         text not null default 'shop' check (location in ('shop','mobile')),
  lat              double precision,
  lng              double precision,
  address          text,
  price_halalas    integer not null default 0,
  discount_halalas integer not null default 0,
  fee_halalas      integer not null default 0,
  total_halalas    integer not null default 0,
  due_now_halalas  integer not null default 0,
  paid_halalas     integer not null default 0,
  offer_id         uuid,
  moyasar_id       text unique,
  pay_flag         text,                       -- 'amount_mismatch' | 'needs_refund'
  token_hash       bytea,
  lang             text not null default 'ar',
  source           text not null default 'web' check (source in ('web','embed','link','owner','walkin','admin')),
  service_name_ar  text,
  service_name_en  text,
  staff_label_ar   text,
  staff_label_en   text,
  cancelled_at     timestamptz,
  cancel_reason    text,
  created_at       timestamptz not null default now(),
  updated_at       timestamptz not null default now(),
  constraint bookings_time check (ends_at > starts_at),
  -- The heart of it: one staff member can never hold two overlapping live bookings.
  constraint bookings_staff_excl exclude using gist (staff_id with =, busy with &&)
    where (staff_id is not null and status in ('pending_payment','confirmed'))
);
create index if not exists bookings_business_time_idx on public.bookings(business_id, starts_at);
create index if not exists bookings_resource_busy_idx on public.bookings using gist (resource_id, busy)
  where (status in ('pending_payment','confirmed'));
create index if not exists bookings_phone_idx on public.bookings(business_id, phone);
create index if not exists bookings_token_idx on public.bookings(token_hash);

create table if not exists public.waitlist (
  id          uuid primary key default gen_random_uuid(),
  business_id uuid not null references public.businesses(id) on delete cascade,
  service_id  uuid references public.services(id) on delete cascade,
  day         date not null,
  part        text not null default 'any' check (part in ('any','morning','afternoon','evening')),
  qty         integer not null default 1,
  name        text not null default '',
  phone       text not null,
  status      text not null default 'waiting' check (status in ('waiting','contacted','booked','removed')),
  created_at  timestamptz not null default now()
);
create index if not exists waitlist_business_idx on public.waitlist(business_id, day);

-- Local adhan times per city and day, filled a year at a time from platform/prayer.js (Umm al-Qura).
create table if not exists public.prayer_times (
  city    text not null,
  day     date not null,
  fajr    time not null,
  dhuhr   time not null,
  asr     time not null,
  maghrib time not null,
  isha    time not null,
  primary key (city, day)
);

-- The doorbell. Clients listen to version bumps, then re-fetch through RPCs.
-- business_id = nil uuid is Ahmed's admin channel. No personal data ever lives here.
create table if not exists public.live_pings (
  business_id uuid primary key,
  catalog_v   bigint not null default 0,
  slots_v     bigint not null default 0,
  admin_v     bigint not null default 0,
  updated_at  timestamptz not null default now()
);

-- ───────────────────────── selling Mamar ─────────────────────────

create table if not exists public.price_items (
  key            text primary key,
  grp            text not null,
  label_ar       text not null,
  label_en       text not null,
  desc_ar        text not null default '',
  desc_en        text not null default '',
  amount_halalas integer,               -- null = custom quote
  per_unit       boolean not null default false,
  sort           integer not null default 0,
  active         boolean not null default true
);

create table if not exists public.plans (
  code            text primary key check (code in ('care','live')),
  name_ar         text not null,
  name_en         text not null,
  desc_ar         text not null default '',
  desc_en         text not null default '',
  monthly_halalas integer not null,
  yearly_halalas  integer not null,
  sort            integer not null default 0
);

create table if not exists public.setup_requests (
  id            uuid primary key default gen_random_uuid(),
  ref           text not null unique,
  status        text not null default 'new'
                check (status in ('draft','new','reviewing','quoted','converted','declined')),
  source        text not null default 'web' check (source in ('web','assisted')),
  business_name text not null default '',
  contact_name  text not null default '',
  phone         text,
  email         text,
  lang          text not null default 'ar',
  answers       jsonb not null default '{}',
  estimate      jsonb not null default '{}',   -- recomputed on the server; the client's total is ignored
  setup_halalas integer not null default 0,
  plan_code     text,
  plan_interval text,
  plan_halalas  integer not null default 0,
  business_id   uuid references public.businesses(id) on delete set null,
  note          text not null default '',
  created_at    timestamptz not null default now(),
  updated_at    timestamptz not null default now()
);
create index if not exists setup_requests_status_idx on public.setup_requests(status, created_at desc);

create table if not exists public.subscriptions (
  business_id        uuid primary key references public.businesses(id) on delete cascade,
  plan_code          text references public.plans(code),
  interval           text check (interval in ('monthly','yearly')),
  status             text not null default 'none' check (status in ('none','pending','active','past_due','cancelled')),
  requested_code     text,
  requested_interval text,
  requested_at       timestamptz,
  period_end         date,
  updated_at         timestamptz not null default now()
);

-- Web Push endpoints (Ahmed's admin today; owners later).
create table if not exists public.push_subscriptions (
  id         uuid primary key default gen_random_uuid(),
  user_id    uuid not null references auth.users(id) on delete cascade,
  endpoint   text not null unique,
  keys       jsonb not null,
  lang       text not null default 'ar',
  ua         text not null default '',
  created_at timestamptz not null default now()
);

-- Everything Ahmed should hear about. An insert fires the notify webhook (Supabase) / pg_notify (local).
create table if not exists public.notifications (
  id         uuid primary key default gen_random_uuid(),
  kind       text not null,                 -- 'setup_request' | 'plan_request' | 'payment_flag'
  title_ar   text not null,
  title_en   text not null,
  body_ar    text not null default '',
  body_en    text not null default '',
  url        text not null default '/admin/',
  ref_id     uuid,
  read_at    timestamptz,
  created_at timestamptz not null default now()
);
create index if not exists notifications_created_idx on public.notifications(created_at desc);

-- ───────────────────────── row level security ─────────────────────────
-- On for every table, with no policies: nobody reads tables directly. RPCs are security definer.
-- The single exception is live_pings (version counters only), readable for Realtime.

do $$
declare t text;
begin
  foreach t in array array['admins','businesses','business_secrets','members','sections','hours','special_hours',
    'staff','resources','categories','services','offers','blocks','bookings','waitlist','prayer_times',
    'live_pings','price_items','plans','setup_requests','subscriptions','push_subscriptions','notifications'] loop
    execute format('alter table public.%I enable row level security', t);
  end loop;
end $$;

drop policy if exists live_pings_read on public.live_pings;
create policy live_pings_read on public.live_pings for select to anon, authenticated using (true);

-- ───────────────────────── who is calling ─────────────────────────

create or replace function public._is_admin() returns boolean
language sql stable security definer set search_path = public as $$
  select auth.uid() is not null and exists (select 1 from public.admins where user_id = auth.uid())
$$;

create or replace function public._is_member(bid uuid) returns boolean
language sql stable security definer set search_path = public as $$
  select auth.uid() is not null and (
    exists (select 1 from public.members where business_id = bid and user_id = auth.uid())
    or exists (select 1 from public.admins where user_id = auth.uid()))
$$;

create or replace function public._need_member(bid uuid) returns void
language plpgsql stable as $$
begin
  if bid is null or not public._is_member(bid) then perform public._err('NOT_ALLOWED'); end if;
end $$;

create or replace function public._need_admin() returns void
language plpgsql stable as $$
begin
  if not public._is_admin() then perform public._err('NOT_ALLOWED'); end if;
end $$;

-- ───────────────────────── effective configuration ─────────────────────────
-- One place resolves entitlements × settings × defaults. Both the booking flow and every check use it.

create or replace function public._cfg(b public.businesses) returns jsonb
language plpgsql stable as $$
declare
  e jsonb := coalesce(b.entitlements, '{}');
  s jsonb := coalesce(b.settings, '{}');
  pay_mode text := coalesce(s #>> '{payment,mode}', 'shop');
begin
  if not coalesce((e ->> 'payments')::boolean, false) or pay_mode not in ('deposit','full') then
    pay_mode := 'shop';
  end if;
  -- No Moyasar keys yet → never ask a customer to pay (they would be stuck). Locally (mamar.local = on)
  -- demo businesses keep their payment step so the demo payment sheet can be shown.
  if pay_mode <> 'shop' and b.moyasar_pk is null
     and not (b.is_demo and coalesce(current_setting('mamar.local', true), '') = 'on') then
    pay_mode := 'shop';
  end if;
  return jsonb_build_object(
    'notice_min',    greatest(0, coalesce((s ->> 'notice_min')::int, 60)),
    'horizon_days',  least(90, greatest(1, coalesce((s ->> 'horizon_days')::int, 30))),
    'staff_choice',  coalesce((e ->> 'staff_choice')::boolean, false) and coalesce((s ->> 'staff_choice')::boolean, true),
    'sections',      coalesce((e ->> 'sections')::boolean, false),
    'hijri',         coalesce((s ->> 'hijri')::boolean, true),
    'home', case when coalesce((e ->> 'home_service')::boolean, false) then jsonb_build_object(
        'on', true,
        'fee_halalas', greatest(0, coalesce((s #>> '{home,fee_halalas}')::int, 0)),
        'travel_min',  greatest(0, coalesce((s #>> '{home,travel_min}')::int, 30)))
      else jsonb_build_object('on', false, 'fee_halalas', 0, 'travel_min', 0) end,
    'prayer', case when coalesce((e ->> 'prayer')::boolean, false) and coalesce((s #>> '{prayer,on}')::boolean, true)
      then jsonb_build_object(
        'on', true,
        'before_min', greatest(0, coalesce((s #>> '{prayer,before_min}')::int, 0)),
        'after_min',  greatest(5, coalesce((s #>> '{prayer,after_min}')::int, 25)),
        'jumuah_min', greatest(15, coalesce((s #>> '{prayer,jumuah_min}')::int, 60)),
        'fajr',       coalesce((s #>> '{prayer,fajr}')::boolean, false))
      else jsonb_build_object('on', false) end,
    'payment', jsonb_build_object(
        'mode', pay_mode,
        'deposit_kind',  coalesce(s #>> '{payment,deposit_kind}', 'percent'),
        'deposit_value', greatest(0, coalesce((s #>> '{payment,deposit_value}')::int, 20)),
        'ready', b.moyasar_pk is not null),
    'customer', jsonb_build_object('email', coalesce(s #>> '{customer,email}', 'off')),
    'self_manage', case when coalesce((e ->> 'self_manage')::boolean, false)
      then jsonb_build_object('on', true, 'cutoff_hours', greatest(0, coalesce((s #>> '{self_manage,cutoff_hours}')::int, 3)))
      else jsonb_build_object('on', false) end,
    'waitlist',      coalesce((e ->> 'waitlist')::boolean, false),
    'max_per_phone', greatest(1, coalesce((s ->> 'max_per_phone')::int, 3)),
    'hold_min',      15
  );
end $$;

-- ───────────────────────── live doorbell ─────────────────────────

create or replace function public._ping(bid uuid, kind text) returns void
language plpgsql as $$
begin
  if bid is null then return; end if;
  insert into public.live_pings as lp (business_id, catalog_v, slots_v, admin_v)
  values (bid, (kind in ('catalog','both'))::int, (kind in ('slots','both'))::int, (kind = 'admin')::int)
  on conflict (business_id) do update set
    catalog_v  = lp.catalog_v + (kind in ('catalog','both'))::int,
    slots_v    = lp.slots_v   + (kind in ('slots','both'))::int,
    admin_v    = lp.admin_v   + (kind = 'admin')::int,
    updated_at = now();
  perform pg_notify('mamar_live', json_build_object('b', bid, 'k', kind)::text);
end $$;

create or replace function public._admin_bid() returns uuid
language sql immutable as $$ select '00000000-0000-0000-0000-000000000000'::uuid $$;

create or replace function public._live_trg() returns trigger
language plpgsql as $$
declare
  kind text := tg_argv[0];
  bid uuid;
begin
  if tg_op = 'DELETE' then bid := old.business_id; else bid := new.business_id; end if;
  perform public._ping(bid, kind);
  if tg_op = 'UPDATE' and old.business_id is distinct from new.business_id then
    perform public._ping(old.business_id, kind);
  end if;
  return null;
end $$;

create or replace function public._business_live_trg() returns trigger
language plpgsql as $$
begin
  perform public._ping(coalesce(new.id, old.id), 'both');
  return null;
end $$;

do $$
declare t text; k text;
begin
  for t, k in select * from (values
      ('services','both'), ('offers','catalog'), ('categories','catalog'), ('sections','both'),
      ('staff','both'), ('resources','both'), ('hours','both'), ('special_hours','both'),
      ('blocks','slots'), ('bookings','slots'), ('waitlist','slots')) v(t, k) loop
    execute format('drop trigger if exists %I on public.%I', t || '_live', t);
    execute format('create trigger %I after insert or update or delete on public.%I for each row execute function public._live_trg(%L)',
                   t || '_live', t, k);
  end loop;
end $$;

drop trigger if exists businesses_live on public.businesses;
create trigger businesses_live after insert or update on public.businesses
  for each row execute function public._business_live_trg();

-- Notifications: wake the admin channel; locally dev/server.js also listens on mamar_notify.
create or replace function public._notify_trg() returns trigger
language plpgsql as $$
begin
  perform public._ping(public._admin_bid(), 'admin');
  perform pg_notify('mamar_notify', new.id::text);
  return null;
end $$;

drop trigger if exists notifications_notify on public.notifications;
create trigger notifications_notify after insert on public.notifications
  for each row execute function public._notify_trg();

create or replace function public._requests_live_trg() returns trigger
language plpgsql as $$
begin
  perform public._ping(public._admin_bid(), 'admin');
  return null;
end $$;

drop trigger if exists setup_requests_live on public.setup_requests;
create trigger setup_requests_live after insert or update or delete on public.setup_requests
  for each row execute function public._requests_live_trg();

create or replace function public._touch_trg() returns trigger
language plpgsql as $$
begin
  new.updated_at := now();
  return new;
end $$;

do $$
declare t text;
begin
  foreach t in array array['businesses','bookings','setup_requests','subscriptions'] loop
    execute format('drop trigger if exists %I on public.%I', t || '_touch', t);
    execute format('create trigger %I before update on public.%I for each row execute function public._touch_trg()', t || '_touch', t);
  end loop;
end $$;


-- ═════════ 002_booking.sql ═════════
-- Mamar Booking · 002 slot engine and the public booking API
--
-- One function, _slots(), decides what is bookable. pub_slots shows its output and pub_book
-- accepts a start only if _slots() offers it — so a customer can never pick a time the server refuses.

create or replace function public._uuid(t text) returns uuid
language plpgsql immutable as $$
begin
  if t is null or t = '' then return null; end if;
  return t::uuid;
exception when others then
  return null;
end $$;

create or replace function public._int(t text, dflt integer) returns integer
language plpgsql immutable as $$
begin
  if t is null or t = '' then return dflt; end if;
  return t::integer;
exception when others then
  return dflt;
end $$;

create or replace function public._section_for(s public.services, p_section uuid) returns uuid
language sql stable as $$
  select coalesce(
    s.section_id,
    (select id from public.sections where id = p_section and business_id = s.business_id),
    (select id from public.sections where business_id = s.business_id order by sort, id limit 1))
$$;

-- Opening ranges for one business day of one section (special hours win over weekly hours).
create or replace function public._day_ranges(bid uuid, sec uuid, d date)
returns table (open_at timestamptz, close_at timestamptz)
language plpgsql stable as $$
declare
  sp public.special_hours;
begin
  select * into sp from public.special_hours
   where business_id = bid and (section_id = sec or section_id is null) and d between from_date and to_date
   order by (section_id is null), (to_date - from_date), from_date desc
   limit 1;
  if found then
    return query
      select public._at(d, (r ->> 0)::int), public._at(d, (r ->> 1)::int)
      from jsonb_array_elements(sp.ranges) r
      where (r ->> 1)::int > (r ->> 0)::int;
  else
    return query
      select public._at(d, h.open_min), public._at(d, h.close_min)
      from public.hours h
      where h.section_id = sec and h.weekday = extract(dow from d)::int;
  end if;
end $$;

-- Prayer pauses: [adhan − before, adhan + after). Friday's Dhuhr uses the Jumu'ah length.
create or replace function public._prayer_windows(p_city text, d1 date, d2 date, pc jsonb)
returns table (w tstzrange)
language sql stable as $$
  select tstzrange(
           x.t - make_interval(mins => coalesce((pc ->> 'before_min')::int, 0)),
           x.t + make_interval(mins => case when v.nm = 'dhuhr' and extract(isodow from pt.day) = 5
                                            then coalesce((pc ->> 'jumuah_min')::int, 60)
                                            else coalesce((pc ->> 'after_min')::int, 25) end),
           '[)')
  from public.prayer_times pt
  cross join lateral (values ('fajr', pt.fajr), ('dhuhr', pt.dhuhr), ('asr', pt.asr),
                             ('maghrib', pt.maghrib), ('isha', pt.isha)) v(nm, tm)
  cross join lateral (select (pt.day + v.tm) at time zone 'Asia/Riyadh' as t) x
  where pt.city = p_city and pt.day between d1 and d2
    and (v.nm <> 'fajr' or coalesce((pc ->> 'fajr')::boolean, false))
$$;

-- Every bookable start for one service on one business day.
--   staff mode    → staff_ids = free eligible staff, least busy first; left_qty = how many
--   capacity mode → left_qty = places left at the busiest moment of the slot (peak, not sum)
-- p_ignore skips one booking (rescheduling it). p_owner relaxes notice, horizon and prayer pauses.
create or replace function public._slots(
  p_svc uuid, p_day date, p_section uuid default null, p_staff uuid default null,
  p_qty integer default 1, p_loc text default 'shop', p_ignore uuid default null, p_owner boolean default false)
returns table (start_at timestamptz, end_at timestamptz, staff_ids uuid[], left_qty integer)
language plpgsql stable as $$
declare
  s public.services;
  b public.businesses;
  cfg jsonb;
  sec uuid;
  dur interval;
  tail interval;
  step interval;
  earliest timestamptz;
  latest timestamptz;
  pray boolean;
begin
  select * into s from public.services where id = p_svc and active;
  if not found then return; end if;
  select * into b from public.businesses where id = s.business_id;
  cfg := public._cfg(b);
  if s.section_id is not null and p_section is not null and s.section_id <> p_section then return; end if;
  sec := public._section_for(s, p_section);
  if sec is null then return; end if;
  if p_loc not in ('shop','mobile') then return; end if;
  if p_loc = 'mobile' and (s.location = 'shop' or not (cfg #>> '{home,on}')::boolean) then return; end if;
  if p_loc = 'shop' and s.location = 'mobile' then return; end if;
  if p_qty < 1 or p_qty > s.max_qty then return; end if;
  if s.mode = 'staff' and p_qty <> 1 then return; end if;

  dur  := make_interval(mins => s.duration_min);
  tail := make_interval(mins => s.buffer_min
            + case when p_loc = 'mobile' then (cfg #>> '{home,travel_min}')::int else 0 end);
  step := make_interval(mins => s.step_min);
  pray := not p_owner and coalesce((cfg #>> '{prayer,on}')::boolean, false);
  if p_owner then
    earliest := '-infinity';
    latest   := 'infinity';
  else
    earliest := now() + make_interval(mins => (cfg ->> 'notice_min')::int);
    latest   := public._at(public._today() + (cfg ->> 'horizon_days')::int + 1, 0);
  end if;

  return query
  with cand as (
    select gs as st, gs + dur as en, tstzrange(gs, gs + dur + tail, '[)') as br
    from public._day_ranges(b.id, sec, p_day) r
    cross join lateral generate_series(r.open_at, r.close_at - dur, step) gs
    where gs >= earliest and gs < latest
  ),
  open_c as (
    select c.* from cand c
    where not exists (
            select 1 from public.blocks bl
            where bl.business_id = b.id and bl.staff_id is null and bl.resource_id is null
              and (bl.section_id is null or bl.section_id = sec) and bl.during && c.br)
      and (not pray or not exists (
            select 1 from public._prayer_windows(b.city, p_day - 1, p_day + 1, cfg -> 'prayer') pw
            where pw.w && tstzrange(c.st, c.en, '[)')))
  )
  select o.st, o.en, x.ids, x.lft
  from open_c o
  cross join lateral (
    -- staff mode
    select array_agg(sf.id order by sf.load, sf.sort, sf.id) as ids, count(*)::int as lft
    from (
      select st2.id, st2.sort,
        (select count(*) from public.bookings bk2
          where bk2.staff_id = st2.id and bk2.status in ('pending_payment','confirmed')
            and bk2.starts_at >= public._at(p_day, 0) and bk2.starts_at < public._at(p_day + 1, 0)) as load
      from public.staff st2
      where s.mode = 'staff' and st2.business_id = b.id and st2.active
        and (st2.section_id is null or st2.section_id = sec)
        and (st2.services is null or s.id = any(st2.services))
        and (p_staff is null or st2.id = p_staff)
        and not exists (
          select 1 from public.bookings bk
          where bk.staff_id = st2.id and bk.id is distinct from p_ignore
            and (bk.status = 'confirmed' or (bk.status = 'pending_payment' and bk.hold_until > now()))
            and bk.busy && o.br)
        and not exists (select 1 from public.blocks bl where bl.staff_id = st2.id and bl.during && o.br)
    ) sf
    having count(*) > 0
    union all
    -- capacity mode
    select null::uuid[], (r.capacity - pk.peak)::int
    from public.resources r
    cross join lateral (
      select coalesce(max(u.used), 0)::int as peak
      from (
        select (select coalesce(sum(bk.qty), 0) from public.bookings bk
                 where bk.resource_id = r.id and bk.id is distinct from p_ignore
                   and (bk.status = 'confirmed' or (bk.status = 'pending_payment' and bk.hold_until > now()))
                   and bk.busy @> pt.t) as used
        from (
          select lower(o.br) as t
          union
          select lower(bk3.busy) from public.bookings bk3
           where bk3.resource_id = r.id and bk3.id is distinct from p_ignore
             and (bk3.status = 'confirmed' or (bk3.status = 'pending_payment' and bk3.hold_until > now()))
             and bk3.busy && o.br and lower(bk3.busy) > lower(o.br)
        ) pt
      ) u
    ) pk
    where s.mode = 'capacity' and r.id = s.resource_id and r.active
      and not exists (select 1 from public.blocks bl where bl.resource_id = r.id and bl.during && o.br)
      and r.capacity - pk.peak >= p_qty
  ) x
  order by o.st;
end $$;

-- Price for one booking. Offers live now apply; weekday offers apply only when p_at falls on that day.
create or replace function public._price(s public.services, p_at timestamptz, p_qty integer, p_loc text, cfg jsonb)
returns jsonb
language sql stable as $$
  with base as (
    select s.price_halalas * (case when s.per_person then greatest(1, coalesce(p_qty, 1)) else 1 end) as p
  ),
  best as (
    select o.id, o.title_ar, o.title_en,
           least(base.p, case o.kind when 'percent' then round(base.p * o.value / 100.0)::int else o.value end) as d
    from public.offers o, base
    where o.business_id = s.business_id and o.active and o.kind in ('percent','amount')
      and (o.service_ids is null or s.id = any(o.service_ids))
      and (o.starts_at is null or o.starts_at <= now())
      and (o.ends_at is null or o.ends_at > now())
      and (o.weekdays is null
           or (p_at is not null and extract(dow from p_at at time zone 'Asia/Riyadh')::int = any(o.weekdays)))
    order by 4 desc, o.created_at
    limit 1
  ),
  fee as (
    select case when p_loc = 'mobile' then coalesce((cfg #>> '{home,fee_halalas}')::int, 0) else 0 end as f
  )
  select jsonb_build_object(
    'price', base.p, 'discount', coalesce(best.d, 0), 'fee', fee.f,
    'total', base.p - coalesce(best.d, 0) + fee.f,
    'offer_id', best.id, 'offer_ar', best.title_ar, 'offer_en', best.title_en)
  from base cross join fee left join best on true
$$;

create or replace function public._due(total integer, cfg jsonb) returns integer
language sql immutable as $$
  select case cfg #>> '{payment,mode}'
    when 'full' then total
    when 'deposit' then least(total, case cfg #>> '{payment,deposit_kind}'
                                       when 'amount' then (cfg #>> '{payment,deposit_value}')::int
                                       else ceil(total * (cfg #>> '{payment,deposit_value}')::numeric / 100)::int end)
    else 0 end
$$;

-- Load a service whose business is live (or previewable by its members).
create or replace function public._live_service(p_id uuid) returns public.services
language plpgsql stable as $$
declare
  s public.services;
  st text;
begin
  select * into s from public.services where id = p_id and active;
  if not found then perform public._err('NOT_FOUND'); end if;
  select status into st from public.businesses where id = s.business_id;
  if st <> 'active' and not public._is_member(s.business_id) then perform public._err('NOT_FOUND'); end if;
  return s;
end $$;

-- The one place a booking row is written (customers, owners and reschedules all come through here).
create or replace function public._book_core(
  s public.services, b public.businesses, cfg jsonb, v_start timestamptz, v_sec uuid, v_staff uuid,
  v_qty integer, v_loc text, cust jsonb, v_source text, v_owner boolean, v_force boolean)
returns jsonb
language plpgsql as $$
declare
  v_day date := (v_start at time zone 'Asia/Riyadh')::date;
  cand record;
  pr jsonb;
  v_total integer;
  v_due integer;
  v_status text;
  v_token text := public._token();
  v_ref text;
  v_id uuid;
  v_end timestamptz;
  v_tail interval;
  v_sid uuid;
  sec uuid := public._section_for(s, v_sec);
  st public.staff;
begin
  -- Lazily release payment holds that ran out, so they stop blocking the exclusion constraint.
  update public.bookings set status = 'expired'
   where business_id = b.id and status = 'pending_payment' and hold_until <= now();

  -- Capacity is checked under a row lock on the shared resource: concurrent bookers queue here.
  if s.mode = 'capacity' then
    perform 1 from public.resources where id = s.resource_id for update;
  end if;

  select * into cand from (
    select * from public._slots(s.id, v_day,     sec, v_staff, v_qty, v_loc, null, v_owner)
    union all
    select * from public._slots(s.id, v_day - 1, sec, v_staff, v_qty, v_loc, null, v_owner)
  ) x where x.start_at = v_start
  limit 1;

  if not found and not v_force then
    if not v_owner and v_start < now() + make_interval(mins => (cfg ->> 'notice_min')::int) then
      perform public._err('TOO_SOON');
    end if;
    perform public._err('SLOT_TAKEN');
  end if;

  v_end  := v_start + make_interval(mins => s.duration_min);
  v_tail := make_interval(mins => s.buffer_min
              + case when v_loc = 'mobile' then (cfg #>> '{home,travel_min}')::int else 0 end);
  pr      := public._price(s, v_start, v_qty, v_loc, cfg);
  v_total := (pr ->> 'total')::int;
  v_due   := case when v_owner then 0 else public._due(v_total, cfg) end;
  v_status := case when v_due > 0 then 'pending_payment' else 'confirmed' end;

  loop
    v_ref := public._ref('MB');
    exit when not exists (select 1 from public.bookings where ref = v_ref);
  end loop;

  -- Staff mode: try the free chairs, least busy first. An owner forcing a booking onto a chosen chair
  -- tries that chair; if it is genuinely taken the booking stays unassigned rather than double-booked.
  if s.mode = 'staff' and (cand.staff_ids is not null or (v_force and v_staff is not null)) then
    foreach v_sid in array coalesce(cand.staff_ids, array[v_staff]) loop
      begin
        select * into st from public.staff where id = v_sid;
        insert into public.bookings (
          ref, business_id, section_id, service_id, staff_id, resource_id, qty, starts_at, ends_at, busy,
          status, hold_until, name, phone, email, note, location, lat, lng, address,
          price_halalas, discount_halalas, fee_halalas, total_halalas, due_now_halalas, offer_id,
          token_hash, lang, source, service_name_ar, service_name_en, staff_label_ar, staff_label_en)
        values (
          v_ref, b.id, sec, s.id, v_sid, null, 1, v_start, v_end, tstzrange(v_start, v_end + v_tail, '[)'),
          v_status, case when v_due > 0 then now() + make_interval(mins => (cfg ->> 'hold_min')::int) end,
          coalesce(cust ->> 'name', ''), cust ->> 'phone', cust ->> 'email', cust ->> 'note', v_loc,
          (cust ->> 'lat')::double precision, (cust ->> 'lng')::double precision, cust ->> 'address',
          (pr ->> 'price')::int, (pr ->> 'discount')::int, (pr ->> 'fee')::int, v_total, v_due,
          public._uuid(pr ->> 'offer_id'), public._hash(v_token), coalesce(cust ->> 'lang', 'ar'), v_source,
          s.name_ar, s.name_en, st.label_ar, st.label_en)
        returning id into v_id;
        exit;
      exception when exclusion_violation then
        v_id := null;   -- someone took this chair a moment ago; try the next one
      end;
    end loop;
    if v_id is null and not v_force then perform public._err('SLOT_TAKEN'); end if;
  end if;

  if v_id is null then
    -- capacity mode, or an owner forcing a walk-in with no chair free
    insert into public.bookings (
      ref, business_id, section_id, service_id, staff_id, resource_id, qty, starts_at, ends_at, busy,
      status, hold_until, name, phone, email, note, location, lat, lng, address,
      price_halalas, discount_halalas, fee_halalas, total_halalas, due_now_halalas, offer_id,
      token_hash, lang, source, service_name_ar, service_name_en)
    values (
      v_ref, b.id, sec, s.id, null, case when s.mode = 'capacity' then s.resource_id end, v_qty, v_start, v_end,
      tstzrange(v_start, v_end + v_tail, '[)'),
      v_status, case when v_due > 0 then now() + make_interval(mins => (cfg ->> 'hold_min')::int) end,
      coalesce(cust ->> 'name', ''), cust ->> 'phone', cust ->> 'email', cust ->> 'note', v_loc,
      (cust ->> 'lat')::double precision, (cust ->> 'lng')::double precision, cust ->> 'address',
      (pr ->> 'price')::int, (pr ->> 'discount')::int, (pr ->> 'fee')::int, v_total, v_due,
      public._uuid(pr ->> 'offer_id'), public._hash(v_token), coalesce(cust ->> 'lang', 'ar'), v_source,
      s.name_ar, s.name_en)
    returning id into v_id;
  end if;

  return (select jsonb_build_object(
      'booking_id', bk.id, 'ref', bk.ref, 'token', v_token, 'status', bk.status,
      'starts_at', bk.starts_at, 'ends_at', bk.ends_at, 'hold_until', bk.hold_until,
      'qty', bk.qty, 'location', bk.location,
      'service_name_ar', bk.service_name_ar, 'service_name_en', bk.service_name_en,
      'staff_label_ar', bk.staff_label_ar, 'staff_label_en', bk.staff_label_en,
      'price_halalas', bk.price_halalas, 'discount_halalas', bk.discount_halalas, 'fee_halalas', bk.fee_halalas,
      'total_halalas', bk.total_halalas, 'due_now_halalas', bk.due_now_halalas)
    from public.bookings bk where bk.id = v_id);
end $$;

-- ───────────────────────── public reads ─────────────────────────

create or replace function public._public_service(s public.services, cfg jsonb) returns jsonb
language sql stable as $$
  select jsonb_build_object(
    'id', s.id, 'section_id', s.section_id, 'category_id', s.category_id,
    'name_ar', s.name_ar, 'name_en', s.name_en, 'desc_ar', s.desc_ar, 'desc_en', s.desc_en,
    'duration_min', s.duration_min, 'mode', s.mode, 'max_qty', s.max_qty, 'per_person', s.per_person,
    'price_from', s.price_from, 'location', s.location,
    'price', public._price(s, null, 1, 'shop', cfg))
$$;

create or replace function public.pub_business(p jsonb default '{}') returns jsonb
language plpgsql stable security definer set search_path = public, extensions as $$
declare
  b public.businesses;
  cfg jsonb;
begin
  select * into b from public.businesses
   where slug = lower(coalesce(p ->> 'slug', '')) or id = public._uuid(p ->> 'business_id')
   limit 1;
  if not found or (b.status <> 'active' and not public._is_member(b.id)) then
    perform public._err('NOT_FOUND');
  end if;
  cfg := public._cfg(b);
  return jsonb_build_object(
    'business', jsonb_build_object(
      'id', b.id, 'slug', b.slug, 'status', b.status, 'is_demo', b.is_demo, 'kind', b.kind,
      'name_ar', b.name_ar, 'name_en', b.name_en, 'tagline_ar', b.tagline_ar, 'tagline_en', b.tagline_en,
      'phone', b.phone, 'address_ar', b.address_ar, 'address_en', b.address_en,
      'maps_url', b.maps_url, 'site_url', b.site_url, 'instagram', b.instagram,
      'lat', b.lat, 'lng', b.lng, 'city', b.city,
      'langs', to_jsonb(b.langs), 'look', b.look, 'theme', b.theme, 'moyasar_pk', b.moyasar_pk),
    'flow', cfg - 'max_per_phone',
    'sections', coalesce((select jsonb_agg(jsonb_build_object(
        'id', x.id, 'name_ar', x.name_ar, 'name_en', x.name_en, 'audience', x.audience) order by x.sort, x.id)
      from public.sections x where x.business_id = b.id), '[]'),
    'categories', coalesce((select jsonb_agg(jsonb_build_object(
        'id', x.id, 'section_id', x.section_id, 'name_ar', x.name_ar, 'name_en', x.name_en) order by x.sort, x.id)
      from public.categories x where x.business_id = b.id), '[]'),
    'services', coalesce((select jsonb_agg(public._public_service(x, cfg) order by x.sort, x.created_at)
      from public.services x where x.business_id = b.id and x.active), '[]'),
    'staff', case when (cfg ->> 'staff_choice')::boolean then coalesce((select jsonb_agg(jsonb_build_object(
        'id', x.id, 'section_id', x.section_id, 'label_ar', x.label_ar, 'label_en', x.label_en,
        'services', to_jsonb(x.services)) order by x.sort, x.id)
      from public.staff x where x.business_id = b.id and x.active), '[]') else '[]' end,
    'offers', coalesce((select jsonb_agg(jsonb_build_object(
        'id', x.id, 'kind', x.kind, 'value', x.value, 'title_ar', x.title_ar, 'title_en', x.title_en,
        'service_ids', to_jsonb(x.service_ids), 'weekdays', to_jsonb(x.weekdays),
        'starts_at', x.starts_at, 'ends_at', x.ends_at) order by x.created_at)
      from public.offers x where x.business_id = b.id and x.active
        and (x.starts_at is null or x.starts_at <= now()) and (x.ends_at is null or x.ends_at > now())), '[]'),
    'hours', coalesce((select jsonb_agg(jsonb_build_object(
        'section_id', h.section_id, 'weekday', h.weekday, 'open_min', h.open_min, 'close_min', h.close_min)
        order by h.weekday, h.open_min)
      from public.hours h where h.business_id = b.id), '[]'),
    'live', coalesce((select jsonb_build_object('catalog', lp.catalog_v, 'slots', lp.slots_v)
      from public.live_pings lp where lp.business_id = b.id), jsonb_build_object('catalog', 0, 'slots', 0)));
end $$;

-- A customer rescheduling passes their manage token so their own booking doesn't block its own slot.
create or replace function public._own_booking(p_token text, p_service uuid) returns uuid
language sql stable as $$
  select id from public.bookings
  where coalesce(p_token, '') <> '' and token_hash = public._hash(p_token) and service_id = p_service
    and status in ('pending_payment','confirmed')
  limit 1
$$;

create or replace function public.pub_days(p jsonb default '{}') returns jsonb
language plpgsql stable security definer set search_path = public, extensions as $$
declare
  s public.services;
  b public.businesses;
  cfg jsonb;
  t0 date := public._today();
  d date;
  n integer;
  out_days jsonb := '[]';
  v_staff uuid;
  v_qty integer := public._int(p ->> 'qty', 1);
  v_loc text := coalesce(p ->> 'location', 'shop');
  v_ignore uuid;
  v_sec uuid;
begin
  s := public._live_service(public._uuid(p ->> 'service_id'));
  select * into b from public.businesses where id = s.business_id;
  cfg := public._cfg(b);
  v_staff := case when (cfg ->> 'staff_choice')::boolean then public._uuid(p ->> 'staff_id') end;
  v_ignore := public._own_booking(p ->> 'token', s.id);
  v_sec := public._section_for(s, public._uuid(p ->> 'section_id'));
  for d in select generate_series(t0 - 1, t0 + (cfg ->> 'horizon_days')::int, interval '1 day')::date loop
    select count(*) into n
      from public._slots(s.id, d, public._uuid(p ->> 'section_id'), v_staff, v_qty, v_loc, v_ignore, false);
    if d >= t0 or n > 0 then
      -- closed = no opening hours that day at all (vs. open but fully booked)
      out_days := out_days || jsonb_build_array(jsonb_build_object('day', d, 'n', n,
        'closed', not exists (select 1 from public._day_ranges(b.id, v_sec, d))));
    end if;
  end loop;
  return jsonb_build_object('service_id', s.id, 'days', out_days);
end $$;

create or replace function public.pub_slots(p jsonb default '{}') returns jsonb
language plpgsql stable security definer set search_path = public, extensions as $$
declare
  s public.services;
  b public.businesses;
  cfg jsonb;
  d date;
  v_staff uuid;
  v_qty integer := public._int(p ->> 'qty', 1);
  v_loc text := coalesce(p ->> 'location', 'shop');
  v_ignore uuid;
begin
  s := public._live_service(public._uuid(p ->> 'service_id'));
  select * into b from public.businesses where id = s.business_id;
  cfg := public._cfg(b);
  begin
    d := (p ->> 'day')::date;
  exception when others then
    perform public._err('BAD_INPUT');
  end;
  v_staff := case when (cfg ->> 'staff_choice')::boolean then public._uuid(p ->> 'staff_id') end;
  v_ignore := public._own_booking(p ->> 'token', s.id);
  return jsonb_build_object(
    'day', d,
    'slots', coalesce((select jsonb_agg(jsonb_build_object('t', x.start_at, 'end', x.end_at, 'n', x.left_qty)
                                         order by x.start_at)
      from public._slots(s.id, d, public._uuid(p ->> 'section_id'), v_staff, v_qty, v_loc, v_ignore, false) x), '[]'),
    'price', public._price(s, public._at(d, 720), v_qty, v_loc, cfg));
end $$;

-- ───────────────────────── public writes ─────────────────────────

create or replace function public.pub_book(p jsonb default '{}') returns jsonb
language plpgsql security definer set search_path = public, extensions as $$
declare
  s public.services;
  b public.businesses;
  cfg jsonb;
  v_start timestamptz;
  v_phone text := public._phone(p ->> 'phone');
  v_name text := btrim(coalesce(p ->> 'name', ''));
  v_email text := nullif(lower(btrim(coalesce(p ->> 'email', ''))), '');
  v_loc text := coalesce(p ->> 'location', 'shop');
  v_qty integer := public._int(p ->> 'qty', 1);
  v_source text := case when p ->> 'source' in ('web','embed','link') then p ->> 'source' else 'web' end;
  v_staff uuid;
begin
  -- Honeypot: bots fill the invisible "website" field. Answer politely, store nothing.
  if coalesce(p ->> 'website', '') <> '' then
    return jsonb_build_object('ref', public._ref('MB'), 'status', 'confirmed', 'token', public._token());
  end if;

  s := public._live_service(public._uuid(p ->> 'service_id'));
  select * into b from public.businesses where id = s.business_id;
  if b.status <> 'active' then perform public._err('NOT_FOUND'); end if;
  cfg := public._cfg(b);

  begin
    v_start := (p ->> 'start')::timestamptz;
  exception when others then
    perform public._err('BAD_INPUT');
  end;
  if v_start is null then perform public._err('BAD_INPUT'); end if;

  if length(v_name) < 2 or length(v_name) > 80 then perform public._err('BAD_NAME'); end if;
  if v_phone is null then perform public._err('BAD_PHONE'); end if;
  if v_email is not null and v_email !~ '^[^@\s]+@[^@\s]+\.[^@\s]+$' then perform public._err('BAD_EMAIL'); end if;
  if cfg #>> '{customer,email}' = 'required' and v_email is null then perform public._err('BAD_EMAIL'); end if;
  if v_loc = 'mobile' and p ->> 'lat' is null and coalesce(btrim(p ->> 'address'), '') = '' then
    perform public._err('NEED_LOCATION');
  end if;
  v_staff := case when (cfg ->> 'staff_choice')::boolean then public._uuid(p ->> 'staff_id') end;

  -- Abuse limits: a phone can hold a few upcoming bookings; a business takes a burst at most.
  if (select count(*) from public.bookings
       where business_id = b.id and phone = v_phone and status in ('pending_payment','confirmed')
         and starts_at > now()) >= (cfg ->> 'max_per_phone')::int then
    perform public._err('RATE_LIMITED');
  end if;
  if (select count(*) from public.bookings
       where business_id = b.id and created_at > now() - interval '10 minutes'
         and source in ('web','embed','link')) >= 40 then
    perform public._err('RATE_LIMITED');
  end if;

  return public._book_core(s, b, cfg, v_start, public._uuid(p ->> 'section_id'), v_staff, v_qty, v_loc,
    jsonb_build_object('name', v_name, 'phone', v_phone, 'email', v_email,
                       'note', left(nullif(btrim(coalesce(p ->> 'note', '')), ''), 500),
                       'lat', p -> 'lat', 'lng', p -> 'lng',
                       'address', left(nullif(btrim(coalesce(p ->> 'address', '')), ''), 300),
                       'lang', case when p ->> 'lang' = 'en' then 'en' else 'ar' end),
    v_source, false, false);
end $$;

-- What the confirmation / manage page shows. The token is the only key.
create or replace function public._booking_view(bk public.bookings) returns jsonb
language plpgsql stable as $$
declare
  b public.businesses;
  cfg jsonb;
  cut interval;
  can boolean;
begin
  select * into b from public.businesses where id = bk.business_id;
  cfg := public._cfg(b);
  cut := make_interval(hours => coalesce((cfg #>> '{self_manage,cutoff_hours}')::int, 3));
  can := (cfg #>> '{self_manage,on}')::boolean and bk.status in ('pending_payment','confirmed')
         and bk.starts_at - cut > now();
  return jsonb_build_object(
    'booking', jsonb_build_object(
      'id', bk.id, 'ref', bk.ref, 'status', bk.status, 'starts_at', bk.starts_at, 'ends_at', bk.ends_at,
      'hold_until', bk.hold_until, 'service_id', bk.service_id, 'section_id', bk.section_id, 'qty', bk.qty,
      'service_name_ar', bk.service_name_ar, 'service_name_en', bk.service_name_en,
      'staff_label_ar', bk.staff_label_ar, 'staff_label_en', bk.staff_label_en,
      'location', bk.location, 'address', bk.address, 'lat', bk.lat, 'lng', bk.lng,
      'name', bk.name, 'phone', bk.phone, 'note', bk.note,
      'price_halalas', bk.price_halalas, 'discount_halalas', bk.discount_halalas, 'fee_halalas', bk.fee_halalas,
      'total_halalas', bk.total_halalas, 'due_now_halalas', bk.due_now_halalas, 'paid_halalas', bk.paid_halalas,
      'lang', bk.lang),
    'business', jsonb_build_object(
      'id', b.id, 'slug', b.slug, 'name_ar', b.name_ar, 'name_en', b.name_en, 'phone', b.phone,
      'address_ar', b.address_ar, 'address_en', b.address_en, 'maps_url', b.maps_url,
      'langs', to_jsonb(b.langs), 'look', b.look, 'theme', b.theme, 'is_demo', b.is_demo,
      'moyasar_pk', b.moyasar_pk),
    'can_cancel', can,
    'can_reschedule', can,
    'cutoff_hours', coalesce((cfg #>> '{self_manage,cutoff_hours}')::int, 3));
end $$;

create or replace function public.pub_booking(p jsonb default '{}') returns jsonb
language plpgsql stable security definer set search_path = public, extensions as $$
declare
  bk public.bookings;
begin
  select * into bk from public.bookings where token_hash = public._hash(p ->> 'token') limit 1;
  if not found or coalesce(p ->> 'token', '') = '' then perform public._err('NOT_FOUND'); end if;
  return public._booking_view(bk);
end $$;

create or replace function public.pub_cancel(p jsonb default '{}') returns jsonb
language plpgsql security definer set search_path = public, extensions as $$
declare
  bk public.bookings;
  v jsonb;
begin
  select * into bk from public.bookings where token_hash = public._hash(p ->> 'token') limit 1 for update;
  if not found or coalesce(p ->> 'token', '') = '' then perform public._err('NOT_FOUND'); end if;
  v := public._booking_view(bk);
  if not (v ->> 'can_cancel')::boolean then perform public._err('TOO_LATE'); end if;
  update public.bookings
     set status = 'cancelled', cancelled_at = now(), cancel_reason = left(coalesce(p ->> 'reason', 'customer'), 200)
   where id = bk.id
   returning * into bk;
  return public._booking_view(bk);
end $$;

create or replace function public.pub_reschedule(p jsonb default '{}') returns jsonb
language plpgsql security definer set search_path = public, extensions as $$
declare
  bk public.bookings;
  s public.services;
  b public.businesses;
  cfg jsonb;
  v jsonb;
  v_start timestamptz;
  v_day date;
  cand record;
  v_sid uuid;
  st public.staff;
  v_tail interval;
begin
  select * into bk from public.bookings where token_hash = public._hash(p ->> 'token') limit 1 for update;
  if not found or coalesce(p ->> 'token', '') = '' then perform public._err('NOT_FOUND'); end if;
  v := public._booking_view(bk);
  if not (v ->> 'can_reschedule')::boolean then perform public._err('TOO_LATE'); end if;
  select * into s from public.services where id = bk.service_id and active;
  if not found then perform public._err('NOT_FOUND'); end if;
  select * into b from public.businesses where id = bk.business_id;
  cfg := public._cfg(b);
  begin
    v_start := (p ->> 'start')::timestamptz;
  exception when others then
    perform public._err('BAD_INPUT');
  end;
  v_day := (v_start at time zone 'Asia/Riyadh')::date;

  if s.mode = 'capacity' then
    perform 1 from public.resources where id = s.resource_id for update;
  end if;

  select * into cand from (
    select * from public._slots(s.id, v_day,     bk.section_id, null, bk.qty, bk.location, bk.id, false)
    union all
    select * from public._slots(s.id, v_day - 1, bk.section_id, null, bk.qty, bk.location, bk.id, false)
  ) x where x.start_at = v_start limit 1;
  if not found then perform public._err('SLOT_TAKEN'); end if;

  v_sid := case when s.mode <> 'staff' then null
                when bk.staff_id = any(cand.staff_ids) then bk.staff_id
                else cand.staff_ids[1] end;
  select * into st from public.staff where id = v_sid;
  v_tail := upper(bk.busy) - bk.ends_at;

  update public.bookings set
    starts_at = v_start,
    ends_at = v_start + (bk.ends_at - bk.starts_at),
    busy = tstzrange(v_start, v_start + (bk.ends_at - bk.starts_at) + v_tail, '[)'),
    staff_id = v_sid,
    staff_label_ar = st.label_ar,
    staff_label_en = st.label_en
  where id = bk.id
  returning * into bk;
  return public._booking_view(bk);
exception when exclusion_violation then
  perform public._err('SLOT_TAKEN');
end $$;

create or replace function public.pub_waitlist_join(p jsonb default '{}') returns jsonb
language plpgsql security definer set search_path = public, extensions as $$
declare
  s public.services;
  b public.businesses;
  v_phone text := public._phone(p ->> 'phone');
  v_day date;
begin
  s := public._live_service(public._uuid(p ->> 'service_id'));
  select * into b from public.businesses where id = s.business_id;
  if not (public._cfg(b) ->> 'waitlist')::boolean then perform public._err('FEATURE_OFF'); end if;
  if v_phone is null then perform public._err('BAD_PHONE'); end if;
  if length(btrim(coalesce(p ->> 'name', ''))) < 2 then perform public._err('BAD_NAME'); end if;
  begin
    v_day := (p ->> 'day')::date;
  exception when others then
    perform public._err('BAD_INPUT');
  end;
  if v_day < public._today() then perform public._err('BAD_INPUT'); end if;
  if exists (select 1 from public.waitlist where business_id = b.id and phone = v_phone and day = v_day
               and service_id = s.id and status = 'waiting') then
    return jsonb_build_object('ok', true, 'already', true);
  end if;
  if (select count(*) from public.waitlist where phone = v_phone and created_at > now() - interval '1 day') >= 5 then
    perform public._err('RATE_LIMITED');
  end if;
  insert into public.waitlist (business_id, service_id, day, part, qty, name, phone)
  values (b.id, s.id, v_day,
          case when p ->> 'part' in ('morning','afternoon','evening') then p ->> 'part' else 'any' end,
          greatest(1, public._int(p ->> 'qty', 1)), left(btrim(p ->> 'name'), 80), v_phone);
  return jsonb_build_object('ok', true);
end $$;

-- ───────────────────────── payments (Moyasar) ─────────────────────────

create or replace function public.pub_attach_payment(p jsonb default '{}') returns jsonb
language plpgsql security definer set search_path = public, extensions as $$
declare
  bk public.bookings;
begin
  select * into bk from public.bookings
   where id = public._uuid(p ->> 'booking_id') and token_hash = public._hash(p ->> 'token') for update;
  if not found then perform public._err('NOT_FOUND'); end if;
  if coalesce(p ->> 'moyasar_id', '') !~ '^[A-Za-z0-9_-]{6,80}$' then perform public._err('BAD_INPUT'); end if;
  if bk.moyasar_id is not null and bk.moyasar_id <> p ->> 'moyasar_id' then perform public._err('NOT_ALLOWED'); end if;
  update public.bookings set moyasar_id = p ->> 'moyasar_id' where id = bk.id;
  return jsonb_build_object('ok', true);
end $$;

create or replace function public.pub_payment_status(p jsonb default '{}') returns jsonb
language plpgsql stable security definer set search_path = public, extensions as $$
declare
  bk public.bookings;
begin
  select * into bk from public.bookings
   where id = public._uuid(p ->> 'booking_id') and token_hash = public._hash(p ->> 'token');
  if not found then perform public._err('NOT_FOUND'); end if;
  return jsonb_build_object('status', bk.status, 'paid_halalas', bk.paid_halalas,
    'due_now_halalas', bk.due_now_halalas, 'hold_until', bk.hold_until, 'pay_flag', bk.pay_flag,
    'moyasar_id', bk.moyasar_id);
end $$;

create or replace function public.svc_payment_context(p jsonb default '{}') returns jsonb
language plpgsql stable security definer set search_path = public, extensions as $$
declare
  bk public.bookings;
begin
  select * into bk from public.bookings where id = public._uuid(p ->> 'booking_id');
  if not found then perform public._err('NOT_FOUND'); end if;
  return jsonb_build_object(
    'booking_id', bk.id, 'business_id', bk.business_id, 'status', bk.status, 'moyasar_id', bk.moyasar_id,
    'due_now_halalas', bk.due_now_halalas, 'currency', 'SAR',
    'secret_key', (select moyasar_sk from public.business_secrets where business_id = bk.business_id));
end $$;

-- Idempotent: the Edge Function may call it several times for the same payment.
create or replace function public.svc_confirm_payment(p jsonb default '{}') returns jsonb
language plpgsql security definer set search_path = public, extensions as $$
declare
  bk public.bookings;
  b public.businesses;
  v_amount integer := public._int(p ->> 'amount_halalas', -1);
  v_mid text := p ->> 'moyasar_id';
  still_free boolean;
begin
  select * into bk from public.bookings where id = public._uuid(p ->> 'booking_id') for update;
  if not found then perform public._err('NOT_FOUND'); end if;
  if bk.moyasar_id is not null and bk.moyasar_id <> v_mid then perform public._err('NOT_ALLOWED'); end if;
  if bk.paid_halalas > 0 and bk.moyasar_id = v_mid then
    return jsonb_build_object('ok', true, 'already', true, 'status', bk.status);
  end if;
  if coalesce(p ->> 'status', '') <> 'paid' or coalesce(p ->> 'currency', 'SAR') <> 'SAR' then
    return jsonb_build_object('ok', false, 'reason', 'NOT_PAID', 'status', bk.status);
  end if;
  select * into b from public.businesses where id = bk.business_id;

  if v_amount <> bk.due_now_halalas then
    update public.bookings set pay_flag = 'amount_mismatch', moyasar_id = v_mid, paid_halalas = greatest(v_amount, 0)
     where id = bk.id;
    insert into public.notifications (kind, title_ar, title_en, body_ar, body_en, url, ref_id)
    values ('payment_flag', 'مبلغ دفع غير مطابق · ' || b.name_ar, 'Payment amount mismatch · ' || b.name_en,
            bk.ref, bk.ref, '/admin/#/businesses/' || b.id, bk.id);
    return jsonb_build_object('ok', false, 'reason', 'AMOUNT_MISMATCH');
  end if;

  if bk.status = 'pending_payment' or bk.status = 'confirmed' then
    update public.bookings set status = 'confirmed', paid_halalas = v_amount, moyasar_id = v_mid, hold_until = null
     where id = bk.id;
    return jsonb_build_object('ok', true, 'status', 'confirmed');
  end if;

  -- Paid after the hold ran out. Keep the booking if its time is still free; otherwise flag a refund.
  if bk.status = 'expired' then
    select exists (
      select 1 from public._slots(bk.service_id, (bk.starts_at at time zone 'Asia/Riyadh')::date, bk.section_id,
                                  case when bk.staff_id is not null then bk.staff_id end, bk.qty, bk.location, bk.id, true) x
      where x.start_at = bk.starts_at) into still_free;
    if still_free then
      begin
        update public.bookings set status = 'confirmed', paid_halalas = v_amount, moyasar_id = v_mid, hold_until = null
         where id = bk.id;
        return jsonb_build_object('ok', true, 'status', 'confirmed', 'late', true);
      exception when exclusion_violation then
        null;
      end;
    end if;
    update public.bookings set pay_flag = 'needs_refund', paid_halalas = v_amount, moyasar_id = v_mid where id = bk.id;
    insert into public.notifications (kind, title_ar, title_en, body_ar, body_en, url, ref_id)
    values ('payment_flag', 'دفعة تحتاج استرداداً · ' || b.name_ar, 'Payment needs a refund · ' || b.name_en,
            bk.ref, bk.ref, '/admin/#/businesses/' || b.id, bk.id);
    return jsonb_build_object('ok', false, 'reason', 'NEEDS_REFUND');
  end if;

  return jsonb_build_object('ok', false, 'reason', 'BAD_STATE', 'status', bk.status);
end $$;

create or replace function public.svc_expire_holds(p jsonb default '{}') returns jsonb
language plpgsql security definer set search_path = public, extensions as $$
declare
  n integer;
begin
  update public.bookings set status = 'expired' where status = 'pending_payment' and hold_until <= now();
  get diagnostics n = row_count;
  return jsonb_build_object('expired', n);
end $$;

-- Cheap version check for the live doorbell's polling fallback (and the admin channel: nil uuid).
create or replace function public.pub_live(p jsonb default '{}') returns jsonb
language sql stable security definer set search_path = public, extensions as $$
  select coalesce(
    (select jsonb_build_object('catalog', catalog_v, 'slots', slots_v, 'admin', admin_v)
       from public.live_pings where business_id = public._uuid(p ->> 'business_id')),
    jsonb_build_object('catalog', 0, 'slots', 0, 'admin', 0))
$$;


-- ═════════ 003_owner.sql ═════════
-- Mamar Booking · 003 owner dashboard API (own_*)
-- Every function starts with _need_member(business_id): owners see only their own businesses,
-- admins see all. Business ids in nested objects are re-checked against the parent business.

create or replace function public._biz(p jsonb) returns public.businesses
language plpgsql stable as $$
declare
  b public.businesses;
begin
  perform public._need_member(public._uuid(p ->> 'business_id'));
  select * into b from public.businesses where id = public._uuid(p ->> 'business_id');
  if not found then perform public._err('NOT_FOUND'); end if;
  return b;
end $$;

-- Does this row id belong to the business? (null id passes: "none")
create or replace function public._owns(tbl text, rid uuid, bid uuid) returns boolean
language plpgsql stable as $$
declare
  ok boolean;
begin
  if rid is null then return true; end if;
  execute format('select exists (select 1 from public.%I where id = $1 and business_id = $2)', tbl)
    into ok using rid, bid;
  return ok;
end $$;

create or replace function public._need_owns(tbl text, rid uuid, bid uuid) returns void
language plpgsql stable as $$
begin
  if not public._owns(tbl, rid, bid) then perform public._err('NOT_ALLOWED'); end if;
end $$;

create or replace function public._booking_row(bk public.bookings) returns jsonb
language sql stable as $$
  select jsonb_build_object(
    'id', bk.id, 'ref', bk.ref, 'status', bk.status, 'starts_at', bk.starts_at, 'ends_at', bk.ends_at,
    'busy_until', upper(bk.busy), 'hold_until', bk.hold_until,
    'section_id', bk.section_id, 'service_id', bk.service_id, 'staff_id', bk.staff_id, 'resource_id', bk.resource_id,
    'qty', bk.qty, 'service_name_ar', bk.service_name_ar, 'service_name_en', bk.service_name_en,
    'staff_label_ar', bk.staff_label_ar, 'staff_label_en', bk.staff_label_en,
    'name', bk.name, 'phone', bk.phone, 'email', bk.email, 'note', bk.note,
    'location', bk.location, 'address', bk.address, 'lat', bk.lat, 'lng', bk.lng,
    'price_halalas', bk.price_halalas, 'discount_halalas', bk.discount_halalas, 'fee_halalas', bk.fee_halalas,
    'total_halalas', bk.total_halalas, 'due_now_halalas', bk.due_now_halalas, 'paid_halalas', bk.paid_halalas,
    'pay_flag', bk.pay_flag, 'source', bk.source, 'lang', bk.lang, 'created_at', bk.created_at,
    'cancel_reason', bk.cancel_reason)
$$;

-- ───────────────────────── who am I ─────────────────────────

create or replace function public.own_me(p jsonb default '{}') returns jsonb
language plpgsql stable security definer set search_path = public, extensions as $$
declare
  adm boolean := public._is_admin();
begin
  if auth.uid() is null then perform public._err('NOT_ALLOWED'); end if;
  return jsonb_build_object(
    'user_id', auth.uid(),
    'email', (select email from auth.users where id = auth.uid()),
    'is_admin', adm,
    'businesses', coalesce((select jsonb_agg(jsonb_build_object(
        'id', b.id, 'slug', b.slug, 'name_ar', b.name_ar, 'name_en', b.name_en, 'status', b.status,
        'kind', b.kind, 'look', b.look, 'is_demo', b.is_demo, 'langs', to_jsonb(b.langs)) order by b.name_en)
      from public.businesses b
      where adm or exists (select 1 from public.members m where m.business_id = b.id and m.user_id = auth.uid())), '[]'));
end $$;

create or replace function public.own_overview(p jsonb default '{}') returns jsonb
language plpgsql stable security definer set search_path = public, extensions as $$
declare
  b public.businesses := public._biz(p);
  cfg jsonb := public._cfg(b);
begin
  return jsonb_build_object(
    'business', jsonb_build_object(
      'id', b.id, 'slug', b.slug, 'status', b.status, 'is_demo', b.is_demo, 'kind', b.kind,
      'name_ar', b.name_ar, 'name_en', b.name_en, 'tagline_ar', b.tagline_ar, 'tagline_en', b.tagline_en,
      'phone', b.phone, 'address_ar', b.address_ar, 'address_en', b.address_en, 'maps_url', b.maps_url,
      'site_url', b.site_url, 'instagram', b.instagram, 'lat', b.lat, 'lng', b.lng, 'city', b.city,
      'langs', to_jsonb(b.langs), 'look', b.look, 'theme', b.theme,
      'entitlements', b.entitlements, 'settings', b.settings, 'moyasar_ready', b.moyasar_pk is not null,
      'setup_halalas', b.setup_halalas, 'created_at', b.created_at),
    'cfg', cfg,
    'sections', coalesce((select jsonb_agg(to_jsonb(x) order by x.sort, x.id) from public.sections x where x.business_id = b.id), '[]'),
    'categories', coalesce((select jsonb_agg(to_jsonb(x) order by x.sort, x.id) from public.categories x where x.business_id = b.id), '[]'),
    'services', coalesce((select jsonb_agg(to_jsonb(x) || jsonb_build_object('price', public._price(x, null, 1, 'shop', cfg))
                                             order by x.sort, x.created_at)
                          from public.services x where x.business_id = b.id), '[]'),
    'staff', coalesce((select jsonb_agg(to_jsonb(x) order by x.sort, x.id) from public.staff x where x.business_id = b.id), '[]'),
    'resources', coalesce((select jsonb_agg(to_jsonb(x) order by x.sort, x.id) from public.resources x where x.business_id = b.id), '[]'),
    'offers', coalesce((select jsonb_agg(to_jsonb(x) order by x.created_at desc) from public.offers x where x.business_id = b.id), '[]'),
    'hours', coalesce((select jsonb_agg(jsonb_build_object('section_id', x.section_id, 'weekday', x.weekday,
                                         'open_min', x.open_min, 'close_min', x.close_min) order by x.weekday, x.open_min)
                       from public.hours x where x.business_id = b.id), '[]'),
    'special_hours', coalesce((select jsonb_agg(to_jsonb(x) order by x.from_date)
                               from public.special_hours x where x.business_id = b.id and x.to_date >= public._today() - 1), '[]'),
    'subscription', (select to_jsonb(x) from public.subscriptions x where x.business_id = b.id),
    'counts', jsonb_build_object(
      'today', (select count(*) from public.bookings x where x.business_id = b.id
                  and x.status in ('pending_payment','confirmed','completed')
                  and x.starts_at >= public._at(public._today(), 0) and x.starts_at < public._at(public._today() + 1, 0)),
      'upcoming', (select count(*) from public.bookings x where x.business_id = b.id
                  and x.status in ('pending_payment','confirmed') and x.starts_at >= now()),
      'waitlist', (select count(*) from public.waitlist x where x.business_id = b.id and x.status = 'waiting'
                  and x.day >= public._today())),
    'live', coalesce((select jsonb_build_object('catalog', lp.catalog_v, 'slots', lp.slots_v)
                      from public.live_pings lp where lp.business_id = b.id), jsonb_build_object('catalog', 0, 'slots', 0)));
end $$;

-- ───────────────────────── bookings ─────────────────────────

-- p: {business_id, from: 'YYYY-MM-DD', to: 'YYYY-MM-DD'} (Riyadh days, inclusive)
create or replace function public.own_bookings(p jsonb default '{}') returns jsonb
language plpgsql stable security definer set search_path = public, extensions as $$
declare
  b public.businesses := public._biz(p);
  d1 date := coalesce((p ->> 'from')::date, public._today());
  d2 date := coalesce((p ->> 'to')::date, d1);
begin
  if d2 < d1 or d2 - d1 > 92 then perform public._err('BAD_INPUT'); end if;
  return jsonb_build_object(
    'from', d1, 'to', d2,
    'bookings', coalesce((select jsonb_agg(public._booking_row(x) order by x.starts_at)
      from public.bookings x where x.business_id = b.id
        and x.starts_at >= public._at(d1, 0) and x.starts_at < public._at(d2 + 1, 0)
        and (coalesce((p ->> 'all')::boolean, false) or x.status <> 'expired')), '[]'),
    'blocks', coalesce((select jsonb_agg(jsonb_build_object(
        'id', x.id, 'section_id', x.section_id, 'staff_id', x.staff_id, 'resource_id', x.resource_id,
        'starts_at', lower(x.during), 'ends_at', upper(x.during), 'reason', x.reason) order by lower(x.during))
      from public.blocks x where x.business_id = b.id
        and x.during && tstzrange(public._at(d1, 0), public._at(d2 + 1, 0), '[)')), '[]'));
end $$;

-- Free times as the owner sees them (no notice/horizon/prayer limits), with the free staff labels.
create or replace function public.own_slots(p jsonb default '{}') returns jsonb
language plpgsql stable security definer set search_path = public, extensions as $$
declare
  b public.businesses := public._biz(p);
  sid uuid := public._uuid(p ->> 'service_id');
begin
  perform public._need_owns('services', sid, b.id);
  return jsonb_build_object('slots', coalesce((select jsonb_agg(jsonb_build_object(
      't', x.start_at, 'end', x.end_at, 'n', x.left_qty, 'staff_ids', to_jsonb(x.staff_ids)) order by x.start_at)
    from public._slots(sid, (p ->> 'day')::date, public._uuid(p ->> 'section_id'), public._uuid(p ->> 'staff_id'),
                       public._int(p ->> 'qty', 1), coalesce(p ->> 'location', 'shop'),
                       public._uuid(p ->> 'ignore'), true) x), '[]'));
end $$;

-- Walk-ins and phone bookings. force = take it even if nothing is free (staff stays unassigned).
create or replace function public.own_booking_create(p jsonb default '{}') returns jsonb
language plpgsql security definer set search_path = public, extensions as $$
declare
  b public.businesses := public._biz(p);
  s public.services;
  v_phone text := public._phone(p ->> 'phone');
begin
  select * into s from public.services where id = public._uuid(p ->> 'service_id') and business_id = b.id;
  if not found then perform public._err('NOT_FOUND'); end if;
  perform public._need_owns('staff', public._uuid(p ->> 'staff_id'), b.id);
  if coalesce(p ->> 'phone', '') <> '' and v_phone is null then perform public._err('BAD_PHONE'); end if;
  return public._book_core(s, b, public._cfg(b), (p ->> 'start')::timestamptz, public._uuid(p ->> 'section_id'),
    public._uuid(p ->> 'staff_id'), public._int(p ->> 'qty', 1), coalesce(p ->> 'location', 'shop'),
    jsonb_build_object('name', left(btrim(coalesce(p ->> 'name', '')), 80), 'phone', v_phone,
                       'note', left(nullif(btrim(coalesce(p ->> 'note', '')), ''), 500),
                       'address', p ->> 'address', 'lang', coalesce(p ->> 'lang', 'ar')),
    case when coalesce((p ->> 'walkin')::boolean, false) then 'walkin' else 'owner' end,
    true, coalesce((p ->> 'force')::boolean, false));
end $$;

create or replace function public.own_booking_status(p jsonb default '{}') returns jsonb
language plpgsql security definer set search_path = public, extensions as $$
declare
  b public.businesses := public._biz(p);
  bk public.bookings;
  v_status text := p ->> 'status';
begin
  if v_status not in ('confirmed','completed','no_show','cancelled') then perform public._err('BAD_INPUT'); end if;
  update public.bookings set
      status = v_status,
      cancelled_at = case when v_status = 'cancelled' then now() else cancelled_at end,
      cancel_reason = case when v_status = 'cancelled' then coalesce(left(p ->> 'reason', 200), 'owner') else cancel_reason end,
      hold_until = case when v_status = 'confirmed' then null else hold_until end
    where id = public._uuid(p ->> 'booking_id') and business_id = b.id
    returning * into bk;
  if not found then perform public._err('NOT_FOUND'); end if;
  return public._booking_row(bk);
exception when exclusion_violation then
  perform public._err('SLOT_TAKEN');
end $$;

-- Bulk cancel (spam waves): p: {business_id, booking_ids: [...]}
create or replace function public.own_booking_bulk_cancel(p jsonb default '{}') returns jsonb
language plpgsql security definer set search_path = public, extensions as $$
declare
  b public.businesses := public._biz(p);
  n integer;
begin
  update public.bookings set status = 'cancelled', cancelled_at = now(), cancel_reason = 'owner_bulk'
   where business_id = b.id and status in ('pending_payment','confirmed')
     and id in (select public._uuid(x) from jsonb_array_elements_text(coalesce(p -> 'booking_ids', '[]')) x);
  get diagnostics n = row_count;
  return jsonb_build_object('cancelled', n);
end $$;

create or replace function public.own_booking_move(p jsonb default '{}') returns jsonb
language plpgsql security definer set search_path = public, extensions as $$
declare
  b public.businesses := public._biz(p);
  bk public.bookings;
  v_start timestamptz := (p ->> 'start')::timestamptz;
  v_want uuid := public._uuid(p ->> 'staff_id');
  v_force boolean := coalesce((p ->> 'force')::boolean, false);
  v_day date := (v_start at time zone 'Asia/Riyadh')::date;
  cand record;
  v_sid uuid;
  st public.staff;
  v_len interval;
  v_tail interval;
begin
  select * into bk from public.bookings where id = public._uuid(p ->> 'booking_id') and business_id = b.id for update;
  if not found then perform public._err('NOT_FOUND'); end if;
  perform public._need_owns('staff', v_want, b.id);
  select * into cand from (
    select * from public._slots(bk.service_id, v_day,     bk.section_id, v_want, bk.qty, bk.location, bk.id, true)
    union all
    select * from public._slots(bk.service_id, v_day - 1, bk.section_id, v_want, bk.qty, bk.location, bk.id, true)
  ) x where x.start_at = v_start limit 1;
  if not found and not v_force then perform public._err('SLOT_TAKEN'); end if;

  v_sid := case
    when bk.staff_id is null and bk.resource_id is not null then null
    when cand.staff_ids is null then case when v_force then null else bk.staff_id end
    when v_want is not null and v_want = any(cand.staff_ids) then v_want
    when bk.staff_id = any(cand.staff_ids) then bk.staff_id
    else cand.staff_ids[1] end;
  select * into st from public.staff where id = v_sid;
  v_len := bk.ends_at - bk.starts_at;
  v_tail := upper(bk.busy) - bk.ends_at;
  update public.bookings set
      starts_at = v_start, ends_at = v_start + v_len, busy = tstzrange(v_start, v_start + v_len + v_tail, '[)'),
      staff_id = v_sid, staff_label_ar = st.label_ar, staff_label_en = st.label_en
    where id = bk.id
    returning * into bk;
  return public._booking_row(bk);
exception when exclusion_violation then
  perform public._err('SLOT_TAKEN');
end $$;

-- ───────────────────────── blocks ─────────────────────────

create or replace function public.own_block_upsert(p jsonb default '{}') returns jsonb
language plpgsql security definer set search_path = public, extensions as $$
declare
  b public.businesses := public._biz(p);
  x jsonb := coalesce(p -> 'block', '{}');
  v_id uuid := public._uuid(x ->> 'id');
  v_from timestamptz := (x ->> 'starts_at')::timestamptz;
  v_to timestamptz := (x ->> 'ends_at')::timestamptz;
begin
  if v_from is null or v_to is null or v_to <= v_from or v_to - v_from > interval '120 days' then
    perform public._err('BAD_INPUT');
  end if;
  perform public._need_owns('sections', public._uuid(x ->> 'section_id'), b.id);
  perform public._need_owns('staff', public._uuid(x ->> 'staff_id'), b.id);
  perform public._need_owns('resources', public._uuid(x ->> 'resource_id'), b.id);
  if v_id is null then
    insert into public.blocks (business_id, section_id, staff_id, resource_id, during, reason)
    values (b.id, public._uuid(x ->> 'section_id'), public._uuid(x ->> 'staff_id'), public._uuid(x ->> 'resource_id'),
            tstzrange(v_from, v_to, '[)'), left(coalesce(x ->> 'reason', ''), 120))
    returning id into v_id;
  else
    update public.blocks set section_id = public._uuid(x ->> 'section_id'), staff_id = public._uuid(x ->> 'staff_id'),
        resource_id = public._uuid(x ->> 'resource_id'), during = tstzrange(v_from, v_to, '[)'),
        reason = left(coalesce(x ->> 'reason', ''), 120)
      where id = v_id and business_id = b.id;
    if not found then perform public._err('NOT_FOUND'); end if;
  end if;
  return jsonb_build_object('id', v_id);
end $$;

create or replace function public.own_block_delete(p jsonb default '{}') returns jsonb
language plpgsql security definer set search_path = public, extensions as $$
declare
  b public.businesses := public._biz(p);
begin
  delete from public.blocks where id = public._uuid(p ->> 'id') and business_id = b.id;
  return jsonb_build_object('ok', found);
end $$;

-- ───────────────────────── catalogue: live prices ─────────────────────────

create or replace function public.own_service_upsert(p jsonb default '{}') returns jsonb
language plpgsql security definer set search_path = public, extensions as $$
declare
  b public.businesses := public._biz(p);
  x jsonb := coalesce(p -> 'service', '{}');
  v_id uuid := public._uuid(x ->> 'id');
  v_mode text := coalesce(x ->> 'mode', 'staff');
  v_res uuid := public._uuid(x ->> 'resource_id');
  v_loc text := coalesce(x ->> 'location', 'shop');
  v_limit integer := coalesce((b.entitlements ->> 'max_services')::int, 15);
begin
  if btrim(coalesce(x ->> 'name_ar', '') || coalesce(x ->> 'name_en', '')) = '' then perform public._err('BAD_NAME'); end if;
  if v_mode not in ('staff','capacity') or (v_mode = 'capacity' and v_res is null) then perform public._err('BAD_INPUT'); end if;
  if v_loc not in ('shop','mobile','both') then perform public._err('BAD_INPUT'); end if;
  if v_loc <> 'shop' and not coalesce((b.entitlements ->> 'home_service')::boolean, false) then
    perform public._err('FEATURE_OFF');
  end if;
  perform public._need_owns('resources', v_res, b.id);
  perform public._need_owns('sections', public._uuid(x ->> 'section_id'), b.id);
  perform public._need_owns('categories', public._uuid(x ->> 'category_id'), b.id);

  if v_id is null then
    if (select count(*) from public.services where business_id = b.id and active) >= v_limit then
      perform public._err('LIMIT_SERVICES', jsonb_build_object('limit', v_limit));
    end if;
    insert into public.services (business_id, name_ar, name_en) values (b.id, '', '') returning id into v_id;
  elsif not public._owns('services', v_id, b.id) then
    perform public._err('NOT_FOUND');
  elsif coalesce((x ->> 'active')::boolean, true)
        and not (select active from public.services where id = v_id)
        and (select count(*) from public.services where business_id = b.id and active) >= v_limit then
    -- switching an archived service back on counts against the package too
    perform public._err('LIMIT_SERVICES', jsonb_build_object('limit', v_limit));
  end if;

  update public.services set
    section_id    = public._uuid(x ->> 'section_id'),
    category_id   = public._uuid(x ->> 'category_id'),
    name_ar       = left(btrim(coalesce(x ->> 'name_ar', '')), 80),
    name_en       = left(btrim(coalesce(x ->> 'name_en', '')), 80),
    desc_ar       = left(btrim(coalesce(x ->> 'desc_ar', '')), 300),
    desc_en       = left(btrim(coalesce(x ->> 'desc_en', '')), 300),
    duration_min  = least(720, greatest(5, public._int(x ->> 'duration_min', 30))),
    buffer_min    = least(240, greatest(0, public._int(x ->> 'buffer_min', 0))),
    step_min      = least(240, greatest(5, public._int(x ->> 'step_min', 15))),
    mode          = v_mode,
    resource_id   = case when v_mode = 'capacity' then v_res end,
    max_qty       = case when v_mode = 'capacity' then least(50, greatest(1, public._int(x ->> 'max_qty', 1))) else 1 end,
    per_person    = v_mode = 'capacity' and coalesce((x ->> 'per_person')::boolean, false),
    price_halalas = greatest(0, public._int(x ->> 'price_halalas', 0)),
    price_from    = coalesce((x ->> 'price_from')::boolean, false),
    location      = v_loc,
    active        = coalesce((x ->> 'active')::boolean, true),
    sort          = public._int(x ->> 'sort', 0)
  where id = v_id;
  return jsonb_build_object('id', v_id);
end $$;

create or replace function public.own_service_delete(p jsonb default '{}') returns jsonb
language plpgsql security definer set search_path = public, extensions as $$
declare
  b public.businesses := public._biz(p);
  v_id uuid := public._uuid(p ->> 'id');
begin
  if exists (select 1 from public.bookings where service_id = v_id and business_id = b.id) then
    update public.services set active = false where id = v_id and business_id = b.id;
    return jsonb_build_object('ok', true, 'archived', true);
  end if;
  delete from public.services where id = v_id and business_id = b.id;
  return jsonb_build_object('ok', found);
end $$;

create or replace function public.own_category_upsert(p jsonb default '{}') returns jsonb
language plpgsql security definer set search_path = public, extensions as $$
declare
  b public.businesses := public._biz(p);
  x jsonb := coalesce(p -> 'category', '{}');
  v_id uuid := public._uuid(x ->> 'id');
begin
  perform public._need_owns('sections', public._uuid(x ->> 'section_id'), b.id);
  if v_id is null then
    insert into public.categories (business_id, section_id, name_ar, name_en, sort)
    values (b.id, public._uuid(x ->> 'section_id'), left(coalesce(x ->> 'name_ar', ''), 60),
            left(coalesce(x ->> 'name_en', ''), 60), public._int(x ->> 'sort', 0))
    returning id into v_id;
  else
    update public.categories set section_id = public._uuid(x ->> 'section_id'),
        name_ar = left(coalesce(x ->> 'name_ar', ''), 60), name_en = left(coalesce(x ->> 'name_en', ''), 60),
        sort = public._int(x ->> 'sort', 0)
      where id = v_id and business_id = b.id;
    if not found then perform public._err('NOT_FOUND'); end if;
  end if;
  return jsonb_build_object('id', v_id);
end $$;

create or replace function public.own_category_delete(p jsonb default '{}') returns jsonb
language plpgsql security definer set search_path = public, extensions as $$
declare
  b public.businesses := public._biz(p);
begin
  delete from public.categories where id = public._uuid(p ->> 'id') and business_id = b.id;
  return jsonb_build_object('ok', found);
end $$;

create or replace function public.own_offer_upsert(p jsonb default '{}') returns jsonb
language plpgsql security definer set search_path = public, extensions as $$
declare
  b public.businesses := public._biz(p);
  x jsonb := coalesce(p -> 'offer', '{}');
  v_id uuid := public._uuid(x ->> 'id');
  v_kind text := coalesce(x ->> 'kind', 'percent');
  v_value integer := greatest(0, public._int(x ->> 'value', 0));
  v_svcs uuid[];
  v_days smallint[];
begin
  if v_kind not in ('percent','amount','banner') then perform public._err('BAD_INPUT'); end if;
  if v_kind = 'percent' and (v_value < 1 or v_value > 90) then perform public._err('BAD_INPUT'); end if;
  if btrim(coalesce(x ->> 'title_ar', '') || coalesce(x ->> 'title_en', '')) = '' then perform public._err('BAD_NAME'); end if;
  if jsonb_typeof(x -> 'service_ids') = 'array' and jsonb_array_length(x -> 'service_ids') > 0 then
    select array_agg(public._uuid(e)) into v_svcs from jsonb_array_elements_text(x -> 'service_ids') e;
    if exists (select 1 from unnest(v_svcs) u where not public._owns('services', u, b.id) or u is null) then
      perform public._err('NOT_ALLOWED');
    end if;
  end if;
  if jsonb_typeof(x -> 'weekdays') = 'array' and jsonb_array_length(x -> 'weekdays') > 0 then
    select array_agg(distinct e::smallint) into v_days from jsonb_array_elements_text(x -> 'weekdays') e
     where e ~ '^[0-6]$';
  end if;
  if v_id is null then
    insert into public.offers (business_id, kind) values (b.id, v_kind) returning id into v_id;
  elsif not public._owns('offers', v_id, b.id) then
    perform public._err('NOT_FOUND');
  end if;
  update public.offers set
    kind = v_kind, value = case when v_kind = 'banner' then 0 else v_value end, service_ids = v_svcs,
    title_ar = left(coalesce(x ->> 'title_ar', ''), 80), title_en = left(coalesce(x ->> 'title_en', ''), 80),
    starts_at = nullif(x ->> 'starts_at', '')::timestamptz, ends_at = nullif(x ->> 'ends_at', '')::timestamptz,
    weekdays = v_days, active = coalesce((x ->> 'active')::boolean, true)
  where id = v_id;
  return jsonb_build_object('id', v_id);
end $$;

create or replace function public.own_offer_delete(p jsonb default '{}') returns jsonb
language plpgsql security definer set search_path = public, extensions as $$
declare
  b public.businesses := public._biz(p);
begin
  delete from public.offers where id = public._uuid(p ->> 'id') and business_id = b.id;
  return jsonb_build_object('ok', found);
end $$;

-- ───────────────────────── hours ─────────────────────────

-- p: {business_id, section_id, hours: [{weekday, open_min, close_min}, …]} replaces that section's week.
create or replace function public.own_hours_set(p jsonb default '{}') returns jsonb
language plpgsql security definer set search_path = public, extensions as $$
declare
  b public.businesses := public._biz(p);
  sec uuid := public._uuid(p ->> 'section_id');
  h jsonb;
begin
  if sec is null or not public._owns('sections', sec, b.id) then perform public._err('NOT_ALLOWED'); end if;
  delete from public.hours where section_id = sec;
  for h in select * from jsonb_array_elements(coalesce(p -> 'hours', '[]')) loop
    insert into public.hours (business_id, section_id, weekday, open_min, close_min)
    values (b.id, sec, (h ->> 'weekday')::smallint, (h ->> 'open_min')::int, (h ->> 'close_min')::int);
  end loop;
  return jsonb_build_object('ok', true);
exception when check_violation or invalid_text_representation or null_value_not_allowed then
  perform public._err('BAD_INPUT');
end $$;

create or replace function public.own_special_hours_upsert(p jsonb default '{}') returns jsonb
language plpgsql security definer set search_path = public, extensions as $$
declare
  b public.businesses := public._biz(p);
  x jsonb := coalesce(p -> 'item', '{}');
  v_id uuid := public._uuid(x ->> 'id');
  r jsonb;
begin
  perform public._need_owns('sections', public._uuid(x ->> 'section_id'), b.id);
  if jsonb_typeof(coalesce(x -> 'ranges', '[]')) <> 'array' then perform public._err('BAD_INPUT'); end if;
  for r in select * from jsonb_array_elements(coalesce(x -> 'ranges', '[]')) loop
    if (r ->> 0)::int < 0 or (r ->> 0)::int > 1439 or (r ->> 1)::int <= (r ->> 0)::int or (r ->> 1)::int > 2880 then
      perform public._err('BAD_INPUT');
    end if;
  end loop;
  if v_id is null then
    insert into public.special_hours (business_id, from_date, to_date) values (b.id, (x ->> 'from_date')::date, (x ->> 'to_date')::date)
    returning id into v_id;
  elsif not public._owns('special_hours', v_id, b.id) then
    perform public._err('NOT_FOUND');
  end if;
  update public.special_hours set section_id = public._uuid(x ->> 'section_id'),
      from_date = (x ->> 'from_date')::date, to_date = (x ->> 'to_date')::date,
      ranges = coalesce(x -> 'ranges', '[]'), label_ar = left(coalesce(x ->> 'label_ar', ''), 60),
      label_en = left(coalesce(x ->> 'label_en', ''), 60)
    where id = v_id;
  return jsonb_build_object('id', v_id);
exception when check_violation or invalid_datetime_format or null_value_not_allowed then
  perform public._err('BAD_INPUT');
end $$;

create or replace function public.own_special_hours_delete(p jsonb default '{}') returns jsonb
language plpgsql security definer set search_path = public, extensions as $$
declare
  b public.businesses := public._biz(p);
begin
  delete from public.special_hours where id = public._uuid(p ->> 'id') and business_id = b.id;
  return jsonb_build_object('ok', found);
end $$;

-- ───────────────────────── staff & resources ─────────────────────────

create or replace function public.own_staff_upsert(p jsonb default '{}') returns jsonb
language plpgsql security definer set search_path = public, extensions as $$
declare
  b public.businesses := public._biz(p);
  x jsonb := coalesce(p -> 'item', '{}');
  v_id uuid := public._uuid(x ->> 'id');
  v_svcs uuid[];
begin
  perform public._need_owns('sections', public._uuid(x ->> 'section_id'), b.id);
  if btrim(coalesce(x ->> 'label_ar', '') || coalesce(x ->> 'label_en', '')) = '' then perform public._err('BAD_NAME'); end if;
  if jsonb_typeof(x -> 'services') = 'array' then
    select array_agg(public._uuid(e)) into v_svcs from jsonb_array_elements_text(x -> 'services') e;
    if exists (select 1 from unnest(v_svcs) u where u is null or not public._owns('services', u, b.id)) then
      perform public._err('NOT_ALLOWED');
    end if;
  end if;
  if v_id is null then
    insert into public.staff (business_id) values (b.id) returning id into v_id;
  elsif not public._owns('staff', v_id, b.id) then
    perform public._err('NOT_FOUND');
  end if;
  update public.staff set section_id = public._uuid(x ->> 'section_id'),
      label_ar = left(coalesce(x ->> 'label_ar', ''), 40), label_en = left(coalesce(x ->> 'label_en', ''), 40),
      services = v_svcs, active = coalesce((x ->> 'active')::boolean, true), sort = public._int(x ->> 'sort', 0)
    where id = v_id;
  return jsonb_build_object('id', v_id);
end $$;

create or replace function public.own_staff_delete(p jsonb default '{}') returns jsonb
language plpgsql security definer set search_path = public, extensions as $$
declare
  b public.businesses := public._biz(p);
  v_id uuid := public._uuid(p ->> 'id');
begin
  if exists (select 1 from public.bookings where staff_id = v_id) then
    update public.staff set active = false where id = v_id and business_id = b.id;
    return jsonb_build_object('ok', true, 'archived', true);
  end if;
  delete from public.staff where id = v_id and business_id = b.id;
  return jsonb_build_object('ok', found);
end $$;

create or replace function public.own_resource_upsert(p jsonb default '{}') returns jsonb
language plpgsql security definer set search_path = public, extensions as $$
declare
  b public.businesses := public._biz(p);
  x jsonb := coalesce(p -> 'item', '{}');
  v_id uuid := public._uuid(x ->> 'id');
begin
  perform public._need_owns('sections', public._uuid(x ->> 'section_id'), b.id);
  if v_id is null then
    insert into public.resources (business_id) values (b.id) returning id into v_id;
  elsif not public._owns('resources', v_id, b.id) then
    perform public._err('NOT_FOUND');
  end if;
  update public.resources set section_id = public._uuid(x ->> 'section_id'),
      label_ar = left(coalesce(x ->> 'label_ar', ''), 40), label_en = left(coalesce(x ->> 'label_en', ''), 40),
      capacity = least(500, greatest(1, public._int(x ->> 'capacity', 1))),
      active = coalesce((x ->> 'active')::boolean, true), sort = public._int(x ->> 'sort', 0)
    where id = v_id;
  return jsonb_build_object('id', v_id);
end $$;

create or replace function public.own_resource_delete(p jsonb default '{}') returns jsonb
language plpgsql security definer set search_path = public, extensions as $$
declare
  b public.businesses := public._biz(p);
  v_id uuid := public._uuid(p ->> 'id');
begin
  if exists (select 1 from public.services where resource_id = v_id)
     or exists (select 1 from public.bookings where resource_id = v_id) then
    update public.resources set active = false where id = v_id and business_id = b.id;
    return jsonb_build_object('ok', true, 'archived', true);
  end if;
  delete from public.resources where id = v_id and business_id = b.id;
  return jsonb_build_object('ok', found);
end $$;

-- ───────────────────────── settings & profile ─────────────────────────
-- Owners tune only what Ahmed sold them (entitlements); everything else is ignored.

create or replace function public.own_settings_update(p jsonb default '{}') returns jsonb
language plpgsql security definer set search_path = public, extensions as $$
declare
  b public.businesses := public._biz(p);
  e jsonb := coalesce(b.entitlements, '{}');
  x jsonb := coalesce(p -> 'settings', '{}');
  c jsonb := '{}';
begin
  if x ? 'notice_min'   then c := c || jsonb_build_object('notice_min', least(2880, greatest(0, public._int(x ->> 'notice_min', 60)))); end if;
  if x ? 'horizon_days' then c := c || jsonb_build_object('horizon_days', least(90, greatest(1, public._int(x ->> 'horizon_days', 30)))); end if;
  if x ? 'hijri'        then c := c || jsonb_build_object('hijri', coalesce((x ->> 'hijri')::boolean, true)); end if;
  if x ? 'max_per_phone' then c := c || jsonb_build_object('max_per_phone', least(10, greatest(1, public._int(x ->> 'max_per_phone', 3)))); end if;
  if x ? 'customer' and x #>> '{customer,email}' in ('off','optional','required') then
    c := c || jsonb_build_object('customer', jsonb_build_object('email', x #>> '{customer,email}'));
  end if;
  if x ? 'staff_choice' and coalesce((e ->> 'staff_choice')::boolean, false) then
    c := c || jsonb_build_object('staff_choice', coalesce((x ->> 'staff_choice')::boolean, true));
  end if;
  if x ? 'prayer' and coalesce((e ->> 'prayer')::boolean, false) then
    c := c || jsonb_build_object('prayer', jsonb_strip_nulls(jsonb_build_object(
      'on',         (x #>> '{prayer,on}')::boolean,
      'fajr',       (x #>> '{prayer,fajr}')::boolean,
      'before_min', least(30, greatest(0, public._int(x #>> '{prayer,before_min}', null))),
      'after_min',  least(60, greatest(5, public._int(x #>> '{prayer,after_min}', null))),
      'jumuah_min', least(120, greatest(15, public._int(x #>> '{prayer,jumuah_min}', null))))));
  end if;
  if x ? 'payment' and coalesce((e ->> 'payments')::boolean, false) then
    c := c || jsonb_build_object('payment', jsonb_strip_nulls(jsonb_build_object(
      'mode', case when x #>> '{payment,mode}' in ('shop','deposit','full') then x #>> '{payment,mode}' end,
      'deposit_kind', case when x #>> '{payment,deposit_kind}' in ('percent','amount') then x #>> '{payment,deposit_kind}' end,
      'deposit_value', greatest(0, public._int(x #>> '{payment,deposit_value}', null)))));
  end if;
  if x ? 'self_manage' and coalesce((e ->> 'self_manage')::boolean, false) then
    c := c || jsonb_build_object('self_manage', jsonb_build_object(
      'cutoff_hours', least(72, greatest(0, public._int(x #>> '{self_manage,cutoff_hours}', 3)))));
  end if;
  if x ? 'home' and coalesce((e ->> 'home_service')::boolean, false) then
    c := c || jsonb_build_object('home', jsonb_strip_nulls(jsonb_build_object(
      'fee_halalas', least(100000, greatest(0, public._int(x #>> '{home,fee_halalas}', null))),
      'travel_min',  least(180, greatest(0, public._int(x #>> '{home,travel_min}', null))))));
  end if;
  update public.businesses set settings = public._jmerge(settings, c) where id = b.id returning * into b;
  return jsonb_build_object('settings', b.settings, 'cfg', public._cfg(b));
end $$;

create or replace function public.own_profile_update(p jsonb default '{}') returns jsonb
language plpgsql security definer set search_path = public, extensions as $$
declare
  b public.businesses := public._biz(p);
  x jsonb := coalesce(p -> 'profile', '{}');
  v_phone text := public._phone(x ->> 'phone');
begin
  if coalesce(x ->> 'phone', '') <> '' and v_phone is null then perform public._err('BAD_PHONE'); end if;
  update public.businesses set
    name_ar    = case when x ? 'name_ar' then left(btrim(x ->> 'name_ar'), 80) else name_ar end,
    name_en    = case when x ? 'name_en' then left(btrim(x ->> 'name_en'), 80) else name_en end,
    tagline_ar = case when x ? 'tagline_ar' then left(x ->> 'tagline_ar', 140) else tagline_ar end,
    tagline_en = case when x ? 'tagline_en' then left(x ->> 'tagline_en', 140) else tagline_en end,
    phone      = case when x ? 'phone' then v_phone else phone end,
    address_ar = case when x ? 'address_ar' then left(x ->> 'address_ar', 200) else address_ar end,
    address_en = case when x ? 'address_en' then left(x ->> 'address_en', 200) else address_en end,
    maps_url   = case when x ? 'maps_url' then nullif(left(x ->> 'maps_url', 300), '') else maps_url end,
    site_url   = case when x ? 'site_url' then nullif(left(x ->> 'site_url', 300), '') else site_url end,
    instagram  = case when x ? 'instagram' then nullif(left(x ->> 'instagram', 60), '') else instagram end,
    lat        = case when x ? 'lat' then (x ->> 'lat')::double precision else lat end,
    lng        = case when x ? 'lng' then (x ->> 'lng')::double precision else lng end
  where id = b.id;
  return jsonb_build_object('ok', true);
end $$;

-- ───────────────────────── waitlist ─────────────────────────

create or replace function public.own_waitlist(p jsonb default '{}') returns jsonb
language plpgsql stable security definer set search_path = public, extensions as $$
declare
  b public.businesses := public._biz(p);
begin
  return jsonb_build_object('items', coalesce((select jsonb_agg(jsonb_build_object(
      'id', w.id, 'service_id', w.service_id, 'service_name_ar', s.name_ar, 'service_name_en', s.name_en,
      'day', w.day, 'part', w.part, 'qty', w.qty, 'name', w.name, 'phone', w.phone, 'status', w.status,
      'created_at', w.created_at) order by w.day, w.created_at)
    from public.waitlist w left join public.services s on s.id = w.service_id
    where w.business_id = b.id and w.day >= public._today() - 1 and w.status in ('waiting','contacted')), '[]'));
end $$;

create or replace function public.own_waitlist_update(p jsonb default '{}') returns jsonb
language plpgsql security definer set search_path = public, extensions as $$
declare
  b public.businesses := public._biz(p);
begin
  if p ->> 'status' not in ('waiting','contacted','booked','removed') then perform public._err('BAD_INPUT'); end if;
  update public.waitlist set status = p ->> 'status' where id = public._uuid(p ->> 'id') and business_id = b.id;
  return jsonb_build_object('ok', found);
end $$;

-- ───────────────────────── billing (care plans) ─────────────────────────

create or replace function public.own_billing(p jsonb default '{}') returns jsonb
language plpgsql stable security definer set search_path = public, extensions as $$
declare
  b public.businesses := public._biz(p);
begin
  return jsonb_build_object(
    'subscription', coalesce((select to_jsonb(x) from public.subscriptions x where x.business_id = b.id),
                             jsonb_build_object('status', 'none')),
    'plans', coalesce((select jsonb_agg(to_jsonb(x) || jsonb_build_object('yearly_saving_halalas', x.monthly_halalas * 12 - x.yearly_halalas)
                                        order by x.sort) from public.plans x), '[]'),
    'setup_halalas', b.setup_halalas);
end $$;

-- An owner asks to start, switch or stop a care plan. Ahmed confirms it (adm_plan_set) once paid.
create or replace function public.own_plan_request(p jsonb default '{}') returns jsonb
language plpgsql security definer set search_path = public, extensions as $$
declare
  b public.businesses := public._biz(p);
  v_code text := nullif(p ->> 'plan_code', 'none');
  v_int text := coalesce(p ->> 'interval', 'monthly');
  pl public.plans;
  amount integer := 0;
begin
  if v_code is not null and not exists (select 1 from public.plans where code = v_code) then perform public._err('BAD_INPUT'); end if;
  if v_int not in ('monthly','yearly') then perform public._err('BAD_INPUT'); end if;
  insert into public.subscriptions (business_id, status) values (b.id, 'none') on conflict (business_id) do nothing;
  update public.subscriptions set requested_code = coalesce(v_code, 'none'), requested_interval = v_int, requested_at = now()
   where business_id = b.id;
  if v_code is not null then
    select * into pl from public.plans where code = v_code;
    amount := case when v_int = 'yearly' then pl.yearly_halalas else pl.monthly_halalas end;
  end if;
  insert into public.notifications (kind, title_ar, title_en, body_ar, body_en, url, ref_id)
  values ('plan_request',
          'طلب تغيير الباقة · ' || coalesce(nullif(b.name_ar, ''), b.name_en),
          'Plan change request · ' || coalesce(nullif(b.name_en, ''), b.name_ar),
          coalesce(pl.name_ar, 'بدون باقة') || case when v_code is null then '' else ' · ' || (amount / 100)::text || ' ر.س' end,
          coalesce(pl.name_en, 'No plan') || case when v_code is null then '' else ' · ' || (amount / 100)::text || ' SAR / ' || v_int end,
          '/admin/#/businesses/' || b.id, b.id);
  return public.own_billing(p);
end $$;

-- ───────────────────────── push subscriptions ─────────────────────────

create or replace function public.own_push_subscribe(p jsonb default '{}') returns jsonb
language plpgsql security definer set search_path = public, extensions as $$
begin
  if auth.uid() is null then perform public._err('NOT_ALLOWED'); end if;
  if coalesce(p ->> 'endpoint', '') !~ '^https://' or p -> 'keys' ->> 'p256dh' is null or p -> 'keys' ->> 'auth' is null then
    perform public._err('BAD_INPUT');
  end if;
  insert into public.push_subscriptions (user_id, endpoint, keys, lang, ua)
  values (auth.uid(), p ->> 'endpoint', p -> 'keys', case when p ->> 'lang' = 'en' then 'en' else 'ar' end, left(coalesce(p ->> 'ua', ''), 200))
  on conflict (endpoint) do update set user_id = excluded.user_id, keys = excluded.keys, lang = excluded.lang, ua = excluded.ua;
  return jsonb_build_object('ok', true);
end $$;

create or replace function public.own_push_unsubscribe(p jsonb default '{}') returns jsonb
language plpgsql security definer set search_path = public, extensions as $$
begin
  delete from public.push_subscriptions where endpoint = p ->> 'endpoint' and user_id = auth.uid();
  return jsonb_build_object('ok', found);
end $$;


-- Fix a customer's details on a booking (typo in the name, a new phone, a note from the call).
create or replace function public.own_booking_edit(p jsonb default '{}') returns jsonb
language plpgsql security definer set search_path = public, extensions as $$
declare
  b public.businesses := public._biz(p);
  bk public.bookings;
  v_phone text := public._phone(p ->> 'phone');
begin
  if p ? 'phone' and coalesce(p ->> 'phone', '') <> '' and v_phone is null then perform public._err('BAD_PHONE'); end if;
  update public.bookings set
      name  = case when p ? 'name' then left(btrim(coalesce(p ->> 'name', '')), 80) else name end,
      phone = case when p ? 'phone' then v_phone else phone end,
      email = case when p ? 'email' then nullif(lower(btrim(coalesce(p ->> 'email', ''))), '') else email end,
      note  = case when p ? 'note' then left(nullif(btrim(coalesce(p ->> 'note', '')), ''), 500) else note end
    where id = public._uuid(p ->> 'booking_id') and business_id = b.id
    returning * into bk;
  if not found then perform public._err('NOT_FOUND'); end if;
  return public._booking_row(bk);
end $$;


-- ═════════ 004_admin.sql ═════════
-- Mamar Booking · 004 selling Mamar: price sheet, setup requests, admin, notifications.

-- 5,799 SAR / ٥٬٧٩٩ ر.س
create or replace function public._sar(halalas integer, lang text default 'en') returns text
language sql immutable as $$
  select case when lang = 'ar'
    then translate(to_char(coalesce(halalas, 0) / 100, 'FM999,999,990'), '0123456789,', '٠١٢٣٤٥٦٧٨٩٬') || ' ر.س'
    else to_char(coalesce(halalas, 0) / 100, 'FM999,999,990') || ' SAR' end
$$;

-- ───────────────────────── the configurator estimate ─────────────────────────
-- Mirrors platform/estimate.js exactly (a differential test keeps them in step).
-- answers: see platform/contract.js → SETUP_ANSWERS.

create or replace function public._service_count(a jsonb) returns integer
language sql immutable as $$
  select case
    when coalesce((a ->> 'services_later')::boolean, false) or jsonb_typeof(a -> 'services') <> 'array'
      then greatest(0, coalesce(public._int(a ->> 'service_count', 0), 0))
    else jsonb_array_length(a -> 'services') end
$$;

create or replace function public._estimate(a jsonb) returns jsonb
language plpgsql stable as $$
declare
  n integer := public._service_count(a);
  br integer := least(20, greatest(1, coalesce(public._int(a ->> 'branches', 1), 1)));
  v_lines jsonb;
  v_total integer;
  v_code text := nullif(coalesce(a #>> '{plan,code}', 'none'), 'none');
  v_int text := case when a #>> '{plan,interval}' = 'yearly' then 'yearly' else 'monthly' end;
  pl public.plans;
begin
  with chosen(key, qty) as (
              select 'base_standard', 1
    union all select 'look_custom', 1       where a ->> 'look' = 'custom'
    union all select 'langs_both', 1        where a ->> 'langs' = 'both'
    union all select 'staff_choice', 1      where coalesce((a ->> 'staff_choice')::boolean, false)
    union all select 'sections', 1          where coalesce((a ->> 'sections')::boolean, false)
    union all select 'home_service', 1      where coalesce((a ->> 'home_service')::boolean, false)
    union all select 'prayer', 1            where coalesce((a ->> 'prayer')::boolean, false)
    union all select 'hijri', 1             where coalesce((a ->> 'hijri')::boolean, false)
    union all select 'payments', 1          where a ->> 'payment' in ('deposit','full')
    union all select 'customer_email', 1    where a ->> 'customer' = 'name_phone_email'
    union all select 'customer_sms', 1      where a ->> 'customer' = 'sms'
    union all select 'customer_accounts', 1 where a ->> 'customer' = 'accounts'
    union all select 'self_manage', 1       where coalesce((a #>> '{extras,self_manage}')::boolean, false)
    union all select 'waitlist', 1          where coalesce((a #>> '{extras,waitlist}')::boolean, false)
    union all select 'services_16_40', 1    where n between 16 and 40
    union all select 'services_40_plus', 1  where n > 40
    union all select 'branch_extra', br - 1 where br > 1
  )
  select coalesce(jsonb_agg(jsonb_build_object(
           'key', pi.key, 'grp', pi.grp, 'label_ar', pi.label_ar, 'label_en', pi.label_en, 'qty', c.qty,
           'unit_halalas', pi.amount_halalas,
           'amount_halalas', case when pi.amount_halalas is null then null else pi.amount_halalas * c.qty end,
           'quote', pi.amount_halalas is null) order by pi.sort, pi.key), '[]'),
         coalesce(sum(pi.amount_halalas * c.qty), 0)::int
    into v_lines, v_total
    from chosen c join public.price_items pi on pi.key = c.key and pi.active;

  if v_code is not null then
    select * into pl from public.plans where code = v_code;
  end if;

  return jsonb_build_object(
    'lines', v_lines,
    'setup_halalas', v_total,
    'has_quote', exists (select 1 from jsonb_array_elements(v_lines) l where (l ->> 'quote')::boolean),
    'service_count', n,
    'plan', case when pl.code is null then jsonb_build_object('code', 'none', 'amount_halalas', 0)
      else jsonb_build_object(
        'code', pl.code, 'interval', v_int, 'name_ar', pl.name_ar, 'name_en', pl.name_en,
        'amount_halalas', case when v_int = 'yearly' then pl.yearly_halalas else pl.monthly_halalas end,
        'saving_halalas', case when v_int = 'yearly' then pl.monthly_halalas * 12 - pl.yearly_halalas else 0 end) end);
end $$;

create or replace function public.pub_price_sheet(p jsonb default '{}') returns jsonb
language sql stable security definer set search_path = public, extensions as $$
  select jsonb_build_object(
    'items', coalesce((select jsonb_agg(jsonb_build_object(
        'key', key, 'grp', grp, 'label_ar', label_ar, 'label_en', label_en, 'desc_ar', desc_ar, 'desc_en', desc_en,
        'amount_halalas', amount_halalas, 'per_unit', per_unit, 'sort', sort) order by sort, key)
      from public.price_items where active), '[]'),
    'plans', coalesce((select jsonb_agg(jsonb_build_object(
        'code', code, 'name_ar', name_ar, 'name_en', name_en, 'desc_ar', desc_ar, 'desc_en', desc_en,
        'monthly_halalas', monthly_halalas, 'yearly_halalas', yearly_halalas,
        'yearly_saving_halalas', monthly_halalas * 12 - yearly_halalas) order by sort)
      from public.plans), '[]'))
$$;

-- ───────────────────────── setup requests ─────────────────────────

create or replace function public._request_notification(r public.setup_requests) returns void
language plpgsql as $$
begin
  insert into public.notifications (kind, title_ar, title_en, body_ar, body_en, url, ref_id)
  values ('setup_request',
          'طلب جديد · ' || coalesce(nullif(r.answers #>> '{business,name_ar}', ''), r.business_name) || ' · ' || public._sar(r.setup_halalas, 'ar'),
          'New request · ' || coalesce(nullif(r.answers #>> '{business,name_en}', ''), r.business_name) || ' · ' || public._sar(r.setup_halalas, 'en'),
          r.contact_name || case when r.plan_code is not null
            then ' · ' || coalesce((select name_ar from public.plans where code = r.plan_code), '') else '' end,
          r.contact_name || case when r.plan_code is not null
            then ' · ' || coalesce((select name_en from public.plans where code = r.plan_code), '') || ' (' || r.plan_interval || ')' else '' end,
          '/admin/#/requests/' || r.id, r.id);
end $$;

create or replace function public._request_values(a jsonb, contact jsonb) returns jsonb
language plpgsql stable as $$
declare
  est jsonb := public._estimate(a);
begin
  return jsonb_build_object(
    'estimate', est,
    'business_name', left(btrim(coalesce(nullif(a #>> '{business,name_ar}', ''), nullif(a #>> '{business,name_en}', ''), '')), 80),
    'contact_name', left(btrim(coalesce(contact ->> 'name', '')), 80),
    'phone', public._phone(contact ->> 'phone'),
    'email', nullif(lower(btrim(coalesce(contact ->> 'email', ''))), ''));
end $$;

-- The business finished /start/. The total the browser showed is ignored and recomputed here.
create or replace function public.pub_submit_setup(p jsonb default '{}') returns jsonb
language plpgsql security definer set search_path = public, extensions as $$
declare
  a jsonb := coalesce(p -> 'answers', '{}');
  v jsonb;
  r public.setup_requests;
  v_ref text;
begin
  if coalesce(p ->> 'website', '') <> '' then
    return jsonb_build_object('ref', public._ref('SR'), 'estimate', public._estimate(a));
  end if;
  if length(a::text) > 60000 then perform public._err('BAD_INPUT'); end if;
  v := public._request_values(a, coalesce(p -> 'contact', '{}'));
  if length(v ->> 'business_name') < 2 then perform public._err('BAD_NAME', '{"field":"business"}'); end if;
  if length(v ->> 'contact_name') < 2 then perform public._err('BAD_NAME', '{"field":"contact"}'); end if;
  if v ->> 'phone' is null then perform public._err('BAD_PHONE'); end if;
  if (select count(*) from public.setup_requests where phone = v ->> 'phone' and created_at > now() - interval '1 day') >= 3
     or (select count(*) from public.setup_requests where created_at > now() - interval '1 hour' and source = 'web') >= 30 then
    perform public._err('RATE_LIMITED');
  end if;
  loop
    v_ref := public._ref('SR');
    exit when not exists (select 1 from public.setup_requests where ref = v_ref);
  end loop;
  insert into public.setup_requests (ref, status, source, business_name, contact_name, phone, email, lang, answers,
                                     estimate, setup_halalas, plan_code, plan_interval, plan_halalas)
  values (v_ref, 'new', 'web', v ->> 'business_name', v ->> 'contact_name', v ->> 'phone', v ->> 'email',
          case when p ->> 'lang' = 'en' then 'en' else 'ar' end, a, v -> 'estimate',
          (v #>> '{estimate,setup_halalas}')::int, nullif(v #>> '{estimate,plan,code}', 'none'),
          v #>> '{estimate,plan,interval}', coalesce((v #>> '{estimate,plan,amount_halalas}')::int, 0))
  returning * into r;
  perform public._request_notification(r);
  return jsonb_build_object('id', r.id, 'ref', r.ref, 'estimate', r.estimate);
end $$;

-- ───────────────────────── request → business ─────────────────────────

create or replace function public._slugify(t text) returns text
language sql immutable as $$
  select left(trim(both '-' from regexp_replace(lower(coalesce(t, '')), '[^a-z0-9]+', '-', 'g')), 36)
$$;

-- Rough Arabic → Latin for booking links when a business only has an Arabic name (ورد → ward-ish).
create or replace function public._translit(t text) returns text
language plpgsql immutable as $$
declare
  m text[] := array['ا','a','أ','a','إ','i','آ','a','ب','b','ت','t','ث','th','ج','j','ح','h','خ','kh','د','d','ذ','th',
                    'ر','r','ز','z','س','s','ش','sh','ص','s','ض','d','ط','t','ظ','z','ع','a','غ','gh','ف','f','ق','q',
                    'ك','k','ل','l','م','m','ن','n','ه','h','ة','a','و','w','ي','y','ى','a','ء','','ئ','e','ؤ','o'];
  r text := regexp_replace(coalesce(t, ''), '[ً-ْـ]', '', 'g');
begin
  for i in 1 .. array_length(m, 1) / 2 loop
    r := replace(r, m[2 * i - 1], m[2 * i]);
  end loop;
  return r;
end $$;

create or replace function public._unique_slug(want text) returns text
language plpgsql stable as $$
declare
  base text := public._slugify(want);
  s text;
  i integer := 1;
begin
  if length(base) < 3 then base := 'biz-' || lower(substr(replace(gen_random_uuid()::text, '-', ''), 1, 6)); end if;
  s := base;
  while exists (select 1 from public.businesses where slug = s) loop
    i := i + 1;
    s := base || '-' || i;
  end loop;
  return s;
end $$;

create or replace function public._business_from_answers(a jsonb, contact jsonb, p_slug text, p_request uuid, p_setup integer)
returns uuid
language plpgsql as $$
declare
  v_kind text := case when a #>> '{business,kind}' in ('salon','carwash','activity','other') then a #>> '{business,kind}' else 'salon' end;
  v_langs text[] := case a ->> 'langs' when 'both' then array['ar','en'] when 'en' then array['en'] else array['ar'] end;
  n integer := public._service_count(a);
  v_bid uuid;
  v_sec uuid;
  v_res uuid;
  secs uuid[] := '{}';
  v_mode text;
  i integer;
  svc jsonb;
  d text;
  rng jsonb;
  v_staff_n integer := least(30, greatest(1, coalesce(public._int(a #>> '{slots,staff_count}', 1), 1)));
  v_cap integer := least(500, greatest(1, coalesce(public._int(a #>> '{slots,capacity}',
                     case when v_kind = 'activity' then 8 else 2 end), 2)));
  v_hours jsonb := a -> 'hours';
  v_code text := nullif(coalesce(a #>> '{plan,code}', 'none'), 'none');
begin
  v_mode := case when a #>> '{slots,mode}' in ('staff','capacity') then a #>> '{slots,mode}'
                 when v_kind in ('carwash','activity') then 'capacity' else 'staff' end;

  insert into public.businesses (slug, status, kind, name_ar, name_en, phone, site_url, instagram, langs, look, theme,
                                 entitlements, settings, request_id, setup_halalas)
  values (
    public._unique_slug(coalesce(nullif(p_slug, ''), nullif(public._slugify(a #>> '{business,name_en}'), ''),
                                 nullif(public._slugify(public._translit(a #>> '{business,name_ar}')), ''), 'biz')),
    'draft', v_kind,
    left(coalesce(nullif(a #>> '{business,name_ar}', ''), a #>> '{business,name_en}', ''), 80),
    left(coalesce(nullif(a #>> '{business,name_en}', ''), a #>> '{business,name_ar}', ''), 80),
    public._phone(contact ->> 'phone'),
    nullif(left(a #>> '{business,site_url}', 300), ''),
    nullif(left(a #>> '{business,instagram}', 60), ''),
    v_langs,
    case when a ->> 'look' = 'custom' then 'custom' else 'standard' end,
    case when a ->> 'look' = 'custom' then jsonb_strip_nulls(jsonb_build_object(
      'mode', case when a #>> '{brand,mode}' = 'dark' then 'dark' else 'light' end,
      'accent', case when a #>> '{brand,accent}' ~ '^#[0-9A-Fa-f]{6}$' then a #>> '{brand,accent}' end))
    else '{}'::jsonb end,
    jsonb_build_object(
      'langs_both',   a ->> 'langs' = 'both',
      'staff_choice', coalesce((a ->> 'staff_choice')::boolean, false),
      'sections',     coalesce((a ->> 'sections')::boolean, false),
      'home_service', coalesce((a ->> 'home_service')::boolean, false),
      'prayer',       coalesce((a ->> 'prayer')::boolean, false),
      'payments',     a ->> 'payment' in ('deposit','full'),
      'self_manage',  coalesce((a #>> '{extras,self_manage}')::boolean, false),
      'waitlist',     coalesce((a #>> '{extras,waitlist}')::boolean, false),
      'custom_look',  a ->> 'look' = 'custom',
      'max_services', case when n > 40 then 999 when n > 15 then 40 else 15 end),
    jsonb_build_object(
      'payment',  jsonb_build_object('mode', case when a ->> 'payment' in ('deposit','full') then a ->> 'payment' else 'shop' end,
                                     'deposit_kind', 'percent', 'deposit_value', 25),
      'customer', jsonb_build_object('email', case when a ->> 'customer' = 'name_phone_email' then 'optional' else 'off' end),
      'hijri',    coalesce((a ->> 'hijri')::boolean, true),
      'prayer',   jsonb_build_object('on', true)),
    p_request, p_setup)
  returning id into v_bid;

  -- sections
  if coalesce((a ->> 'sections')::boolean, false) then
    insert into public.sections (business_id, name_ar, name_en, audience, sort)
    values (v_bid, 'قسم الرجال', 'Men', 'men', 0) returning id into v_sec;
    secs := secs || v_sec;
    insert into public.sections (business_id, name_ar, name_en, audience, sort)
    values (v_bid, 'قسم النساء', 'Women', 'women', 1) returning id into v_sec;
    secs := secs || v_sec;
  else
    insert into public.sections (business_id, name_ar, name_en, audience, sort)
    values (v_bid, 'الرئيسي', 'Main', 'all', 0) returning id into v_sec;
    secs := secs || v_sec;
  end if;

  -- hours: {"0": [[600, 1320]], …}; default Sat–Thu 10:00–22:00, Fri 16:00–23:00
  if jsonb_typeof(v_hours) <> 'object' then
    v_hours := '{"0":[[600,1320]],"1":[[600,1320]],"2":[[600,1320]],"3":[[600,1320]],"4":[[600,1320]],"5":[[960,1380]],"6":[[600,1320]]}';
  end if;
  foreach v_sec in array secs loop
    for d, rng in select * from jsonb_each(v_hours) loop
      if d ~ '^[0-6]$' and jsonb_typeof(rng) = 'array' then
        insert into public.hours (business_id, section_id, weekday, open_min, close_min)
        select v_bid, v_sec, d::smallint, (r ->> 0)::int, (r ->> 1)::int
        from jsonb_array_elements(rng) r
        where (r ->> 0)::int between 0 and 1439 and (r ->> 1)::int > (r ->> 0)::int and (r ->> 1)::int <= 2880;
      end if;
    end loop;
  end loop;

  -- who or what limits a slot
  if v_mode = 'capacity' then
    insert into public.resources (business_id, label_ar, label_en, capacity)
    values (v_bid,
            case v_kind when 'carwash' then 'المغاسل' when 'activity' then 'المقاعد' else 'الأماكن' end,
            case v_kind when 'carwash' then 'Wash bays' when 'activity' then 'Seats' else 'Places' end,
            v_cap)
    returning id into v_res;
  else
    for i in 1..v_staff_n loop
      insert into public.staff (business_id, label_ar, label_en, sort)
      values (v_bid,
              case v_kind when 'salon' then 'كرسي ' else 'فريق ' end || translate(i::text, '0123456789', '٠١٢٣٤٥٦٧٨٩'),
              case v_kind when 'salon' then 'Chair ' else 'Team ' end || i, i);
    end loop;
  end if;

  -- services (when the business typed them in)
  if not coalesce((a ->> 'services_later')::boolean, false) and jsonb_typeof(a -> 'services') = 'array' then
    i := 0;
    for svc in select * from jsonb_array_elements(a -> 'services') loop
      i := i + 1;
      insert into public.services (business_id, name_ar, name_en, duration_min, price_halalas, mode, resource_id,
                                   max_qty, per_person, sort)
      values (v_bid,
              left(coalesce(nullif(svc ->> 'name_ar', ''), svc ->> 'name', svc ->> 'name_en', ''), 80),
              left(coalesce(nullif(svc ->> 'name_en', ''), svc ->> 'name', svc ->> 'name_ar', ''), 80),
              least(720, greatest(5, coalesce(public._int(svc ->> 'duration_min', 30), 30))),
              greatest(0, round(coalesce((svc ->> 'price_sar')::numeric, 0) * 100))::int,
              v_mode, v_res,
              case when v_mode = 'capacity' then least(50, greatest(1, coalesce(public._int(svc ->> 'max_qty', null),
                case when v_kind = 'activity' then least(8, v_cap) else 1 end))) else 1 end,
              v_mode = 'capacity' and v_kind = 'activity',
              i);
    end loop;
  end if;

  insert into public.subscriptions (business_id, plan_code, interval, status)
  values (v_bid, v_code, case when v_code is null then null when a #>> '{plan,interval}' = 'yearly' then 'yearly' else 'monthly' end,
          case when v_code is null then 'none' else 'pending' end);

  return v_bid;
end $$;

-- ───────────────────────── admin ─────────────────────────

create or replace function public.adm_overview(p jsonb default '{}') returns jsonb
language plpgsql stable security definer set search_path = public, extensions as $$
begin
  perform public._need_admin();
  return jsonb_build_object(
    'requests', jsonb_build_object(
      'new', (select count(*) from public.setup_requests where status = 'new'),
      'open', (select count(*) from public.setup_requests where status in ('new','reviewing','quoted')),
      'drafts', (select count(*) from public.setup_requests where status = 'draft')),
    'businesses', jsonb_build_object(
      'active', (select count(*) from public.businesses where status = 'active' and not is_demo),
      'awaiting_payment', (select count(*) from public.businesses where status = 'awaiting_payment'),
      'draft', (select count(*) from public.businesses where status = 'draft'),
      'demo', (select count(*) from public.businesses where is_demo)),
    'plans', jsonb_build_object(
      -- demo businesses never count as revenue
      'active', (select count(*) from public.subscriptions s join public.businesses b on b.id = s.business_id
                 where s.status = 'active' and not b.is_demo),
      'requested', (select count(*) from public.subscriptions s join public.businesses b on b.id = s.business_id
                    where s.requested_code is not null and not b.is_demo),
      'mrr_halalas', coalesce((select sum(case when s.interval = 'yearly' then pl.yearly_halalas / 12 else pl.monthly_halalas end)
                               from public.subscriptions s join public.plans pl on pl.code = s.plan_code
                               join public.businesses b on b.id = s.business_id
                               where s.status = 'active' and not b.is_demo), 0)),
    'bookings_today', (select count(*) from public.bookings bk
                        where not exists (select 1 from public.businesses b where b.id = bk.business_id and b.is_demo)
                          and status in ('confirmed','completed','pending_payment')
                          and starts_at >= public._at(public._today(), 0) and starts_at < public._at(public._today() + 1, 0)),
    'unread', (select count(*) from public.notifications where read_at is null),
    'notifications', coalesce((select jsonb_agg(to_jsonb(n) order by n.created_at desc)
                               from (select * from public.notifications order by created_at desc limit 12) n), '[]'));
end $$;

create or replace function public.adm_requests(p jsonb default '{}') returns jsonb
language plpgsql stable security definer set search_path = public, extensions as $$
begin
  perform public._need_admin();
  return jsonb_build_object('items', coalesce((select jsonb_agg(jsonb_build_object(
      'id', r.id, 'ref', r.ref, 'status', r.status, 'source', r.source, 'business_name', r.business_name,
      'name_ar', r.answers #>> '{business,name_ar}', 'name_en', r.answers #>> '{business,name_en}',
      'kind', r.answers #>> '{business,kind}', 'contact_name', r.contact_name, 'phone', r.phone, 'email', r.email,
      'setup_halalas', r.setup_halalas, 'plan_code', r.plan_code, 'plan_interval', r.plan_interval,
      'plan_halalas', r.plan_halalas, 'business_id', r.business_id, 'created_at', r.created_at,
      'updated_at', r.updated_at) order by r.created_at desc)
    from public.setup_requests r
    where (p ->> 'status' is null and r.status <> 'draft') or r.status = p ->> 'status'), '[]'));
end $$;

create or replace function public.adm_request(p jsonb default '{}') returns jsonb
language plpgsql stable security definer set search_path = public, extensions as $$
declare
  r public.setup_requests;
begin
  perform public._need_admin();
  select * into r from public.setup_requests where id = public._uuid(p ->> 'id');
  if not found then perform public._err('NOT_FOUND'); end if;
  return to_jsonb(r);
end $$;

create or replace function public.adm_request_update(p jsonb default '{}') returns jsonb
language plpgsql security definer set search_path = public, extensions as $$
declare
  r public.setup_requests;
begin
  perform public._need_admin();
  if p ? 'status' and p ->> 'status' not in ('new','reviewing','quoted','converted','declined') then
    perform public._err('BAD_INPUT');
  end if;
  update public.setup_requests set
      status = coalesce(p ->> 'status', status),
      note = case when p ? 'note' then left(p ->> 'note', 4000) else note end
    where id = public._uuid(p ->> 'id')
    returning * into r;
  if not found then perform public._err('NOT_FOUND'); end if;
  return to_jsonb(r);
end $$;

create or replace function public.adm_request_delete(p jsonb default '{}') returns jsonb
language plpgsql security definer set search_path = public, extensions as $$
begin
  perform public._need_admin();
  delete from public.setup_requests where id = public._uuid(p ->> 'id') and business_id is null;
  return jsonb_build_object('ok', found);
end $$;

-- Assisted mode: Ahmed fills /start/ for a client. Drafts survive across devices.
create or replace function public.adm_draft_save(p jsonb default '{}') returns jsonb
language plpgsql security definer set search_path = public, extensions as $$
declare
  a jsonb := coalesce(p -> 'answers', '{}');
  v jsonb := public._request_values(a, coalesce(p -> 'contact', '{}'));
  v_id uuid := public._uuid(p ->> 'id');
  v_ref text;
begin
  perform public._need_admin();
  if v_id is not null and exists (select 1 from public.setup_requests where id = v_id and status = 'draft') then
    update public.setup_requests set answers = a, estimate = v -> 'estimate',
        business_name = v ->> 'business_name', contact_name = v ->> 'contact_name', phone = v ->> 'phone',
        email = v ->> 'email', setup_halalas = (v #>> '{estimate,setup_halalas}')::int,
        plan_code = nullif(v #>> '{estimate,plan,code}', 'none'), plan_interval = v #>> '{estimate,plan,interval}',
        plan_halalas = coalesce((v #>> '{estimate,plan,amount_halalas}')::int, 0),
        lang = case when p ->> 'lang' = 'en' then 'en' else 'ar' end
      where id = v_id;
  else
    loop
      v_ref := public._ref('SR');
      exit when not exists (select 1 from public.setup_requests where ref = v_ref);
    end loop;
    insert into public.setup_requests (ref, status, source, business_name, contact_name, phone, email, lang, answers,
                                       estimate, setup_halalas, plan_code, plan_interval, plan_halalas)
    values (v_ref, 'draft', 'assisted', v ->> 'business_name', v ->> 'contact_name', v ->> 'phone', v ->> 'email',
            case when p ->> 'lang' = 'en' then 'en' else 'ar' end, a, v -> 'estimate',
            (v #>> '{estimate,setup_halalas}')::int, nullif(v #>> '{estimate,plan,code}', 'none'),
            v #>> '{estimate,plan,interval}', coalesce((v #>> '{estimate,plan,amount_halalas}')::int, 0))
    returning id into v_id;
  end if;
  return (select jsonb_build_object('id', r.id, 'ref', r.ref, 'estimate', r.estimate, 'updated_at', r.updated_at)
          from public.setup_requests r where r.id = v_id);
end $$;

-- Finish assisted mode: save as a request, and optionally create the business straight away.
create or replace function public.adm_submit_assisted(p jsonb default '{}') returns jsonb
language plpgsql security definer set search_path = public, extensions as $$
declare
  saved jsonb;
  r public.setup_requests;
  v_bid uuid;
begin
  perform public._need_admin();
  saved := public.adm_draft_save(p);
  update public.setup_requests set status = 'new' where id = (saved ->> 'id')::uuid returning * into r;
  if length(r.business_name) < 2 then perform public._err('BAD_NAME'); end if;
  if coalesce((p ->> 'create')::boolean, false) then
    v_bid := public._business_from_answers(r.answers, jsonb_build_object('phone', r.phone), p ->> 'slug', r.id, r.setup_halalas);
    update public.setup_requests set status = 'converted', business_id = v_bid where id = r.id returning * into r;
  end if;
  return jsonb_build_object('request_id', r.id, 'ref', r.ref, 'business_id', v_bid,
    'slug', (select slug from public.businesses where id = v_bid), 'estimate', r.estimate);
end $$;

create or replace function public.adm_business_create(p jsonb default '{}') returns jsonb
language plpgsql security definer set search_path = public, extensions as $$
declare
  r public.setup_requests;
  v_bid uuid;
begin
  perform public._need_admin();
  select * into r from public.setup_requests where id = public._uuid(p ->> 'request_id') for update;
  if not found then perform public._err('NOT_FOUND'); end if;
  if r.business_id is not null then
    return jsonb_build_object('business_id', r.business_id, 'slug', (select slug from public.businesses where id = r.business_id), 'existing', true);
  end if;
  v_bid := public._business_from_answers(r.answers, jsonb_build_object('phone', r.phone), p ->> 'slug', r.id, r.setup_halalas);
  update public.setup_requests set status = 'converted', business_id = v_bid where id = r.id;
  return jsonb_build_object('business_id', v_bid, 'slug', (select slug from public.businesses where id = v_bid));
end $$;

create or replace function public.adm_businesses(p jsonb default '{}') returns jsonb
language plpgsql stable security definer set search_path = public, extensions as $$
begin
  perform public._need_admin();
  return jsonb_build_object('items', coalesce((select jsonb_agg(jsonb_build_object(
      'id', b.id, 'slug', b.slug, 'status', b.status, 'is_demo', b.is_demo, 'kind', b.kind,
      'name_ar', b.name_ar, 'name_en', b.name_en, 'look', b.look, 'langs', to_jsonb(b.langs),
      'setup_halalas', b.setup_halalas, 'created_at', b.created_at,
      'plan_code', s.plan_code, 'plan_interval', s.interval, 'plan_status', s.status,
      'plan_requested', s.requested_code, 'plan_requested_interval', s.requested_interval,
      'owners', (select count(*) from public.members m where m.business_id = b.id),
      'upcoming', (select count(*) from public.bookings x where x.business_id = b.id
                     and x.status in ('pending_payment','confirmed') and x.starts_at >= now()))
      order by b.is_demo, b.created_at desc)
    from public.businesses b left join public.subscriptions s on s.business_id = b.id), '[]'));
end $$;

create or replace function public.adm_business(p jsonb default '{}') returns jsonb
language plpgsql stable security definer set search_path = public, extensions as $$
declare
  b public.businesses;
begin
  perform public._need_admin();
  select * into b from public.businesses where id = public._uuid(p ->> 'business_id');
  if not found then perform public._err('NOT_FOUND'); end if;
  return public.own_overview(jsonb_build_object('business_id', b.id)) || jsonb_build_object(
    'members', coalesce((select jsonb_agg(jsonb_build_object('user_id', m.user_id, 'email', u.email, 'role', m.role))
                         from public.members m join auth.users u on u.id = m.user_id where m.business_id = b.id), '[]'),
    'request', (select to_jsonb(r) from public.setup_requests r where r.id = b.request_id),
    'secrets', jsonb_build_object('moyasar_pk', b.moyasar_pk,
                                  'has_sk', exists (select 1 from public.business_secrets s where s.business_id = b.id and s.moyasar_sk is not null)),
    'pay_flags', coalesce((select jsonb_agg(public._booking_row(x) order by x.created_at desc)
                           from public.bookings x where x.business_id = b.id and x.pay_flag is not null), '[]'));
end $$;

create or replace function public.adm_business_update(p jsonb default '{}') returns jsonb
language plpgsql security definer set search_path = public, extensions as $$
declare
  b public.businesses;
  x jsonb := coalesce(p -> 'patch', '{}');
  v_langs text[];
begin
  perform public._need_admin();
  select * into b from public.businesses where id = public._uuid(p ->> 'business_id') for update;
  if not found then perform public._err('NOT_FOUND'); end if;
  if x ? 'status' and x ->> 'status' not in ('draft','awaiting_payment','active','paused') then perform public._err('BAD_INPUT'); end if;
  if x ? 'look' and x ->> 'look' not in ('standard','custom') then perform public._err('BAD_INPUT'); end if;
  if x ? 'kind' and x ->> 'kind' not in ('salon','carwash','activity','other') then perform public._err('BAD_INPUT'); end if;
  if x ? 'slug' and (x ->> 'slug' !~ '^[a-z0-9][a-z0-9-]{1,38}[a-z0-9]$'
                     or exists (select 1 from public.businesses where slug = x ->> 'slug' and id <> b.id)) then
    perform public._err('SLUG_TAKEN');
  end if;
  if x ? 'langs' then
    select array_agg(distinct l) into v_langs from jsonb_array_elements_text(x -> 'langs') l where l in ('ar','en');
    if v_langs is null then perform public._err('BAD_INPUT'); end if;
  end if;
  update public.businesses set
    status       = coalesce(x ->> 'status', status),
    slug         = coalesce(x ->> 'slug', slug),
    kind         = coalesce(x ->> 'kind', kind),
    name_ar      = coalesce(left(x ->> 'name_ar', 80), name_ar),
    name_en      = coalesce(left(x ->> 'name_en', 80), name_en),
    look         = coalesce(x ->> 'look', look),
    langs        = coalesce(v_langs, langs),
    theme        = case when x ? 'theme' and jsonb_typeof(x -> 'theme') = 'object' then x -> 'theme' else theme end,
    entitlements = case when x ? 'entitlements' then public._jmerge(entitlements, x -> 'entitlements') else entitlements end,
    settings     = case when x ? 'settings' then public._jmerge(settings, x -> 'settings') else settings end,
    is_demo      = coalesce((x ->> 'is_demo')::boolean, is_demo),
    city         = coalesce(x ->> 'city', city),
    setup_halalas = case when x ? 'setup_halalas' then public._int(x ->> 'setup_halalas', setup_halalas) else setup_halalas end,
    phone        = case when x ? 'phone' then public._phone(x ->> 'phone') else phone end
  where id = b.id
  returning * into b;
  return jsonb_build_object('id', b.id, 'slug', b.slug, 'status', b.status);
end $$;

-- On Supabase: create the user in Dashboard → Authentication → Add user, then attach by email here.
create or replace function public.adm_attach_owner(p jsonb default '{}') returns jsonb
language plpgsql security definer set search_path = public, extensions as $$
declare
  v_uid uuid;
begin
  perform public._need_admin();
  if not exists (select 1 from public.businesses where id = public._uuid(p ->> 'business_id')) then perform public._err('NOT_FOUND'); end if;
  select id into v_uid from auth.users where lower(email) = lower(btrim(coalesce(p ->> 'email', '')));
  if v_uid is null then perform public._err('USER_NOT_FOUND'); end if;
  insert into public.members (business_id, user_id, role) values (public._uuid(p ->> 'business_id'), v_uid, 'owner')
  on conflict do nothing;
  return jsonb_build_object('ok', true, 'user_id', v_uid);
end $$;

create or replace function public.adm_detach_owner(p jsonb default '{}') returns jsonb
language plpgsql security definer set search_path = public, extensions as $$
begin
  perform public._need_admin();
  delete from public.members where business_id = public._uuid(p ->> 'business_id') and user_id = public._uuid(p ->> 'user_id');
  return jsonb_build_object('ok', found);
end $$;

create or replace function public.adm_set_moyasar_keys(p jsonb default '{}') returns jsonb
language plpgsql security definer set search_path = public, extensions as $$
declare
  v_bid uuid := public._uuid(p ->> 'business_id');
begin
  perform public._need_admin();
  if coalesce(p ->> 'pk', '') !~ '^pk_(test|live)_[A-Za-z0-9]+$' then perform public._err('BAD_INPUT'); end if;
  if coalesce(p ->> 'sk', '') <> '' and p ->> 'sk' !~ '^sk_(test|live)_[A-Za-z0-9]+$' then perform public._err('BAD_INPUT'); end if;
  update public.businesses set moyasar_pk = p ->> 'pk' where id = v_bid;
  if not found then perform public._err('NOT_FOUND'); end if;
  if coalesce(p ->> 'sk', '') <> '' then
    insert into public.business_secrets (business_id, moyasar_sk) values (v_bid, p ->> 'sk')
    on conflict (business_id) do update set moyasar_sk = excluded.moyasar_sk, updated_at = now();
  end if;
  return jsonb_build_object('ok', true);
end $$;

create or replace function public.adm_price_items_update(p jsonb default '{}') returns jsonb
language plpgsql security definer set search_path = public, extensions as $$
declare
  x jsonb;
  n integer := 0;
begin
  perform public._need_admin();
  for x in select * from jsonb_array_elements(coalesce(p -> 'items', '[]')) loop
    update public.price_items set
      amount_halalas = case when x ? 'amount_halalas' then public._int(x ->> 'amount_halalas', null) else amount_halalas end,
      label_ar = coalesce(left(x ->> 'label_ar', 120), label_ar),
      label_en = coalesce(left(x ->> 'label_en', 120), label_en),
      desc_ar  = coalesce(left(x ->> 'desc_ar', 400), desc_ar),
      desc_en  = coalesce(left(x ->> 'desc_en', 400), desc_en),
      active   = coalesce((x ->> 'active')::boolean, active)
    where key = x ->> 'key';
    n := n + (case when found then 1 else 0 end);
  end loop;
  return jsonb_build_object('updated', n) || public.pub_price_sheet('{}');
end $$;

create or replace function public.adm_plans_update(p jsonb default '{}') returns jsonb
language plpgsql security definer set search_path = public, extensions as $$
declare
  x jsonb;
begin
  perform public._need_admin();
  for x in select * from jsonb_array_elements(coalesce(p -> 'plans', '[]')) loop
    update public.plans set
      monthly_halalas = coalesce(public._int(x ->> 'monthly_halalas', null), monthly_halalas),
      yearly_halalas  = coalesce(public._int(x ->> 'yearly_halalas', null), yearly_halalas),
      name_ar = coalesce(left(x ->> 'name_ar', 60), name_ar), name_en = coalesce(left(x ->> 'name_en', 60), name_en),
      desc_ar = coalesce(left(x ->> 'desc_ar', 400), desc_ar), desc_en = coalesce(left(x ->> 'desc_en', 400), desc_en)
    where code = x ->> 'code';
  end loop;
  return public.pub_price_sheet('{}');
end $$;

-- Confirm a care plan once the business has paid (or stop one).
create or replace function public.adm_plan_set(p jsonb default '{}') returns jsonb
language plpgsql security definer set search_path = public, extensions as $$
declare
  v_bid uuid := public._uuid(p ->> 'business_id');
  v_code text := nullif(p ->> 'plan_code', 'none');
begin
  perform public._need_admin();
  if v_code is not null and not exists (select 1 from public.plans where code = v_code) then perform public._err('BAD_INPUT'); end if;
  if coalesce(p ->> 'status', 'active') not in ('none','pending','active','past_due','cancelled') then perform public._err('BAD_INPUT'); end if;
  insert into public.subscriptions (business_id, status) values (v_bid, 'none') on conflict (business_id) do nothing;
  update public.subscriptions set
    plan_code = v_code,
    interval = case when v_code is null then null when p ->> 'interval' = 'yearly' then 'yearly' else 'monthly' end,
    status = case when v_code is null then 'none' else coalesce(p ->> 'status', 'active') end,
    period_end = nullif(p ->> 'period_end', '')::date,
    requested_code = null, requested_interval = null, requested_at = null
  where business_id = v_bid;
  return (select to_jsonb(s) from public.subscriptions s where s.business_id = v_bid);
end $$;

-- rows: [{day, fajr, dhuhr, asr, maghrib, isha}] from platform/prayer.js
create or replace function public.adm_prayer_upsert(p jsonb default '{}') returns jsonb
language plpgsql security definer set search_path = public, extensions as $$
declare
  v_city text := coalesce(nullif(p ->> 'city', ''), 'jeddah');
  n integer;
begin
  perform public._need_admin();
  insert into public.prayer_times (city, day, fajr, dhuhr, asr, maghrib, isha)
  select v_city, (r ->> 'day')::date, (r ->> 'fajr')::time, (r ->> 'dhuhr')::time, (r ->> 'asr')::time,
         (r ->> 'maghrib')::time, (r ->> 'isha')::time
  from jsonb_array_elements(coalesce(p -> 'rows', '[]')) r
  on conflict (city, day) do update set fajr = excluded.fajr, dhuhr = excluded.dhuhr, asr = excluded.asr,
    maghrib = excluded.maghrib, isha = excluded.isha;
  get diagnostics n = row_count;
  return jsonb_build_object('upserted', n) || public.adm_prayer_status(jsonb_build_object('city', v_city));
end $$;

create or replace function public.adm_prayer_status(p jsonb default '{}') returns jsonb
language plpgsql stable security definer set search_path = public, extensions as $$
declare
  v_city text := coalesce(nullif(p ->> 'city', ''), 'jeddah');
begin
  perform public._need_admin();
  return (select jsonb_build_object('city', v_city, 'first_day', min(day), 'last_day', max(day), 'days', count(*),
                                    'days_left', coalesce(max(day) - public._today(), 0))
          from public.prayer_times where city = v_city);
end $$;

create or replace function public.adm_notifications(p jsonb default '{}') returns jsonb
language plpgsql stable security definer set search_path = public, extensions as $$
begin
  perform public._need_admin();
  return jsonb_build_object('items', coalesce((select jsonb_agg(to_jsonb(n) order by n.created_at desc)
    from (select * from public.notifications order by created_at desc
          limit least(200, greatest(1, public._int(p ->> 'limit', 50)))) n), '[]'),
    'unread', (select count(*) from public.notifications where read_at is null));
end $$;

create or replace function public.adm_notifications_read(p jsonb default '{}') returns jsonb
language plpgsql security definer set search_path = public, extensions as $$
begin
  perform public._need_admin();
  update public.notifications set read_at = now()
   where read_at is null
     and (coalesce((p ->> 'all')::boolean, false)
          or id in (select public._uuid(x) from jsonb_array_elements_text(coalesce(p -> 'ids', '[]')) x));
  return jsonb_build_object('unread', (select count(*) from public.notifications where read_at is null));
end $$;

-- ───────────────────────── server-side (Edge Function / dev server) ─────────────────────────

-- Everything the notify function needs for one notification: the texts, the request (for the
-- email) and every admin's push endpoints.
create or replace function public.svc_notification(p jsonb default '{}') returns jsonb
language plpgsql stable security definer set search_path = public, extensions as $$
declare
  n public.notifications;
begin
  select * into n from public.notifications where id = public._uuid(p ->> 'id');
  if not found then perform public._err('NOT_FOUND'); end if;
  return jsonb_build_object(
    'notification', to_jsonb(n),
    'request', case when n.kind = 'setup_request'
                 then (select to_jsonb(r) from public.setup_requests r where r.id = n.ref_id) end,
    'targets', coalesce((select jsonb_agg(jsonb_build_object('endpoint', s.endpoint, 'keys', s.keys, 'lang', s.lang))
                         from public.push_subscriptions s join public.admins a on a.user_id = s.user_id), '[]'));
end $$;

create or replace function public.svc_push_gone(p jsonb default '{}') returns jsonb
language plpgsql security definer set search_path = public, extensions as $$
begin
  delete from public.push_subscriptions where endpoint = p ->> 'endpoint';
  return jsonb_build_object('ok', found);
end $$;

-- "Send me a test notification" from the admin (exercises push + email end to end).
create or replace function public.adm_notify_test(p jsonb default '{}') returns jsonb
language plpgsql security definer set search_path = public, extensions as $$
begin
  perform public._need_admin();
  insert into public.notifications (kind, title_ar, title_en, body_ar, body_en, url)
  values ('test', 'تجربة إشعار من ممر', 'Test notification from Mamar',
          'إذا وصلك هذا فالإشعارات تعمل.', 'If you can read this, notifications work.', '/admin/');
  return jsonb_build_object('ok', true);
end $$;


