-- ═════════ 006_invites.sql ═════════
-- Mamar Booking · 006 sign-in by email link, owner invites, server-side secrets.
--
-- Nobody creates passwords for anyone: Ahmed and the owners sign in with a link emailed to them.
-- The first time an address signs in, Supabase creates its auth user and the trigger below turns it
-- into an admin (if it is on admin_emails) and/or a member of every business that invited it.

create table if not exists public.admin_emails (
  email      text primary key check (email = lower(email)),
  created_at timestamptz not null default now()
);

create table if not exists public.member_invites (
  business_id uuid not null references public.businesses(id) on delete cascade,
  email       text not null check (email = lower(email)),
  created_at  timestamptz not null default now(),
  primary key (business_id, email)
);

-- Keys the server generates for itself (VAPID for Web Push, the webhook secret). Never typed by a
-- person, never in the repo, readable only through svc_ functions.
create table if not exists public.app_secrets (
  key        text primary key,
  value      text not null,
  updated_at timestamptz not null default now()
);

alter table public.admin_emails enable row level security;
alter table public.member_invites enable row level security;
alter table public.app_secrets enable row level security;

insert into public.app_secrets (key, value)
values ('hook_secret', replace(gen_random_uuid()::text || gen_random_uuid()::text, '-', ''))
on conflict (key) do nothing;

-- New auth user → admin and/or owner, by email.
create or replace function public._on_auth_user() returns trigger
language plpgsql security definer set search_path = public as $$
declare
  e text := lower(coalesce(new.email, ''));
begin
  if e = '' then return new; end if;
  if exists (select 1 from public.admin_emails where email = e) then
    insert into public.admins (user_id) values (new.id) on conflict do nothing;
  end if;
  insert into public.members (business_id, user_id, role)
  select business_id, new.id, 'owner' from public.member_invites where email = e
  on conflict do nothing;
  delete from public.member_invites where email = e;
  return new;
end $$;

drop trigger if exists mamar_on_auth_user on auth.users;
create trigger mamar_on_auth_user after insert on auth.users
  for each row execute function public._on_auth_user();

-- Attach an owner by email. If they have never signed in, they are invited: the first time they
-- sign in at mamar.site/manage with that email, they land straight in their dashboard.
create or replace function public.adm_attach_owner(p jsonb default '{}') returns jsonb
language plpgsql security definer set search_path = public, extensions as $$
declare
  v_bid uuid := public._uuid(p ->> 'business_id');
  v_email text := lower(btrim(coalesce(p ->> 'email', '')));
  v_uid uuid;
begin
  perform public._need_admin();
  if not exists (select 1 from public.businesses where id = v_bid) then perform public._err('NOT_FOUND'); end if;
  if v_email !~ '^[^@\s]+@[^@\s]+\.[^@\s]+$' then perform public._err('BAD_EMAIL'); end if;
  select id into v_uid from auth.users where lower(email) = v_email;
  if v_uid is null then
    insert into public.member_invites (business_id, email) values (v_bid, v_email) on conflict do nothing;
    return jsonb_build_object('ok', true, 'invited', true, 'email', v_email);
  end if;
  insert into public.members (business_id, user_id, role) values (v_bid, v_uid, 'owner') on conflict do nothing;
  return jsonb_build_object('ok', true, 'user_id', v_uid, 'email', v_email);
end $$;

create or replace function public.adm_invite_cancel(p jsonb default '{}') returns jsonb
language plpgsql security definer set search_path = public, extensions as $$
begin
  perform public._need_admin();
  delete from public.member_invites
   where business_id = public._uuid(p ->> 'business_id') and email = lower(btrim(coalesce(p ->> 'email', '')));
  return jsonb_build_object('ok', found);
end $$;

create or replace function public.adm_invites(p jsonb default '{}') returns jsonb
language plpgsql stable security definer set search_path = public, extensions as $$
begin
  perform public._need_admin();
  return jsonb_build_object('items', coalesce((select jsonb_agg(jsonb_build_object('email', email, 'created_at', created_at)
    order by created_at) from public.member_invites where business_id = public._uuid(p ->> 'business_id')), '[]'));
end $$;

-- Secrets for the notify function (it creates its own VAPID keys on first run).
create or replace function public.svc_secret_get(p jsonb default '{}') returns jsonb
language sql stable security definer set search_path = public as $$
  select jsonb_build_object('value', (select value from public.app_secrets where key = p ->> 'key'))
$$;

create or replace function public.svc_secret_set(p jsonb default '{}') returns jsonb
language plpgsql security definer set search_path = public as $$
begin
  insert into public.app_secrets (key, value) values (p ->> 'key', p ->> 'value')
  on conflict (key) do nothing;          -- first writer wins; never overwrite a live key
  return jsonb_build_object('value', (select value from public.app_secrets where key = p ->> 'key'));
end $$;


-- ═════════ 007_chat.sql ═════════
-- Mamar Booking · 007 the website assistant's daily caps.
--
-- The `chat` Edge Function asks svc_chat_take before every answer. It counts one message for the visitor
-- (a SHA-256 of their IP — never the IP itself) and one for the whole site, per Jeddah day, and says
-- whether both are still under their caps. Rows older than a week are dropped as it goes.

create table if not exists public.chat_usage (
  day  date not null,
  who  text not null,                  -- visitor hash, or '*' for the site-wide total
  n    integer not null default 0,
  primary key (day, who)
);
alter table public.chat_usage enable row level security;

create or replace function public.svc_chat_take(p jsonb default '{}') returns jsonb
language plpgsql security definer set search_path = public, extensions as $$
declare
  d     date := (now() at time zone 'Asia/Riyadh')::date;
  v_who text := left(coalesce(p ->> 'who', ''), 80);
  mine  integer;
  total integer;
begin
  if v_who = '' or v_who = '*' then perform public._err('BAD_INPUT'); end if;
  insert into public.chat_usage (day, who, n) values (d, v_who, 1)
    on conflict (day, who) do update set n = chat_usage.n + 1 returning n into mine;
  insert into public.chat_usage (day, who, n) values (d, '*', 1)
    on conflict (day, who) do update set n = chat_usage.n + 1 returning n into total;
  delete from public.chat_usage where day < d - 7;
  return jsonb_build_object(
    'ok', mine <= coalesce((p ->> 'per_visitor')::int, 25) and total <= coalesce((p ->> 'per_day')::int, 600),
    'mine', mine, 'total', total);
end $$;

-- How busy the assistant has been (admin): today and the last seven days.
create or replace function public.adm_chat_stats(p jsonb default '{}') returns jsonb
language plpgsql stable security definer set search_path = public, extensions as $$
declare d date := (now() at time zone 'Asia/Riyadh')::date;
begin
  perform public._need_admin();
  return jsonb_build_object(
    'today', coalesce((select n from public.chat_usage where day = d and who = '*'), 0),
    'week', coalesce((select sum(n) from public.chat_usage where day > d - 7 and who = '*'), 0),
    'visitors_today', (select count(*) from public.chat_usage where day = d and who <> '*'));
end $$;


-- ═════════ 008_chat_contact.sql ═════════
-- Mamar Booking · 008 "talk to a person" from the website assistant.
--
-- When a visitor asks for Ahmed, the chat shows a small form (name, WhatsApp number, message). The `chat`
-- Edge Function passes it to svc_chat_contact, which stores it with the last few chat turns and raises a
-- notification — so it arrives like a setup request: push, email (with a one-tap WhatsApp reply) and the
-- admin's chat page. Limits: 3 a day per visitor, 3 a day per number, 40 a day for the whole site.

create table if not exists public.chat_contacts (
  id          uuid primary key default gen_random_uuid(),
  name        text not null,
  phone       text not null,                    -- E.164
  message     text not null default '',
  lang        text not null default 'ar',
  transcript  jsonb not null default '[]',      -- [{role, content}], the last few turns before the form
  who         text not null default '',         -- visitor hash (as in chat_usage), for the daily limit
  status      text not null default 'new' check (status in ('new','done')),
  created_at  timestamptz not null default now(),
  done_at     timestamptz
);
create index if not exists chat_contacts_status_idx on public.chat_contacts(status, created_at desc);
alter table public.chat_contacts enable row level security;

create or replace function public.svc_chat_contact(p jsonb default '{}') returns jsonb
language plpgsql security definer set search_path = public, extensions as $$
declare
  v_name  text := left(btrim(regexp_replace(coalesce(p ->> 'name', ''), '\s+', ' ', 'g')), 80);
  v_phone text := public._phone(p ->> 'phone');
  v_msg   text := left(btrim(coalesce(p ->> 'message', '')), 1000);
  v_lang  text := case when p ->> 'lang' = 'en' then 'en' else 'ar' end;
  v_who   text := left(coalesce(p ->> 'who', ''), 80);
  v_tr    jsonb := '[]';
  c       public.chat_contacts;
begin
  if v_name = '' or v_phone is null then perform public._err('BAD_INPUT'); end if;
  if (select count(*) from public.chat_contacts where created_at > now() - interval '1 day'
        and ((v_who <> '' and who = v_who) or phone = v_phone)) >= 3
     or (select count(*) from public.chat_contacts where created_at > now() - interval '1 day') >= 40 then
    perform public._err('RATE_LIMITED');
  end if;
  -- keep at most the last 8 turns, each trimmed, as plain {role, content}
  select coalesce(jsonb_agg(jsonb_build_object('role', case when e ->> 'role' = 'assistant' then 'assistant' else 'user' end,
                                               'content', left(coalesce(e ->> 'content', ''), 500)) order by o), '[]')
    into v_tr
    from (select e, o from jsonb_array_elements(case when jsonb_typeof(p -> 'transcript') = 'array' then p -> 'transcript' else '[]' end)
            with ordinality as x(e, o) order by o desc limit 8) t;

  insert into public.chat_contacts (name, phone, message, lang, transcript, who)
  values (v_name, v_phone, v_msg, v_lang, v_tr, v_who) returning * into c;

  insert into public.notifications (kind, title_ar, title_en, body_ar, body_en, url, ref_id)
  values ('chat_contact', 'رسالة من محادثة الموقع · ' || v_name, 'Website chat message · ' || v_name,
          coalesce(nullif(left(v_msg, 140), ''), 'يريد التحدث معك') || ' · ' || v_phone,
          coalesce(nullif(left(v_msg, 140), ''), 'Would like to talk to you') || ' · ' || v_phone,
          '/admin/#/chat', c.id);
  return jsonb_build_object('ok', true);
end $$;

-- The admin's chat page: the messages (newest first) and how busy the assistant has been.
create or replace function public.adm_chat_contacts(p jsonb default '{}') returns jsonb
language plpgsql stable security definer set search_path = public, extensions as $$
begin
  perform public._need_admin();
  return jsonb_build_object('items', coalesce((
    select jsonb_agg(to_jsonb(c) - 'who' order by c.status = 'done', c.created_at desc)
      from (select * from public.chat_contacts order by created_at desc limit 100) c), '[]'));
end $$;

create or replace function public.adm_chat_contact_set(p jsonb default '{}') returns jsonb
language plpgsql security definer set search_path = public, extensions as $$
declare v_status text := p ->> 'status';
begin
  perform public._need_admin();
  if v_status not in ('new', 'done') then perform public._err('BAD_INPUT'); end if;
  update public.chat_contacts set status = v_status, done_at = case when v_status = 'done' then now() end
   where id = public._uuid(p ->> 'id');
  if not found then perform public._err('NOT_FOUND'); end if;
  perform public._ping(public._admin_bid(), 'admin');
  return jsonb_build_object('ok', true);
end $$;

create or replace function public.adm_chat_stats(p jsonb default '{}') returns jsonb
language plpgsql stable security definer set search_path = public, extensions as $$
declare d date := (now() at time zone 'Asia/Riyadh')::date;
begin
  perform public._need_admin();
  return jsonb_build_object(
    'today', coalesce((select n from public.chat_usage where day = d and who = '*'), 0),
    'week', coalesce((select sum(n) from public.chat_usage where day > d - 7 and who = '*'), 0),
    'visitors_today', (select count(*) from public.chat_usage where day = d and who <> '*'),
    'open_contacts', (select count(*) from public.chat_contacts where status = 'new'));
end $$;

-- The notify function reads this: for a chat message it now also gets the message itself.
create or replace function public.svc_notification(p jsonb default '{}') returns jsonb
language plpgsql stable security definer set search_path = public, extensions as $$
declare
  n public.notifications;
begin
  select * into n from public.notifications where id = public._uuid(p ->> 'id');
  if not found then perform public._err('NOT_FOUND'); end if;
  return jsonb_build_object(
    'notification', to_jsonb(n),
    'request', case when n.kind = 'setup_request'
                 then (select to_jsonb(r) from public.setup_requests r where r.id = n.ref_id) end,
    'contact', case when n.kind = 'chat_contact'
                 then (select to_jsonb(c) - 'who' from public.chat_contacts c where c.id = n.ref_id) end,
    'targets', coalesce((select jsonb_agg(jsonb_build_object('endpoint', s.endpoint, 'keys', s.keys, 'lang', s.lang))
                         from public.push_subscriptions s join public.admins a on a.user_id = s.user_id), '[]'));
end $$;


-- ═════════ 999_grants.sql ═════════
-- Mamar Booking · 999 grants. Always run last (and again after adding any function).
--
-- Postgres gives EXECUTE on every new function to PUBLIC, and Supabase adds default grants to
-- anon/authenticated. Both are revoked here, then granted back strictly by name prefix:
--   pub_ → anon, authenticated     own_, adm_ → authenticated     svc_ → service_role
--   _internal → nobody (they run inside security definer functions)

alter default privileges in schema public revoke execute on functions from public;

grant usage on schema public to anon, authenticated, service_role;

do $$
declare
  f record;
begin
  for f in
    select p.oid::regprocedure as sig, p.proname as name
    from pg_proc p join pg_namespace n on n.oid = p.pronamespace
    where n.nspname = 'public' and p.prokind = 'f'
  loop
    execute format('revoke all on function %s from public, anon, authenticated, service_role', f.sig);
    if f.name like 'pub\_%' then
      execute format('grant execute on function %s to anon, authenticated, service_role', f.sig);
    elsif f.name like 'own\_%' or f.name like 'adm\_%' then
      execute format('grant execute on function %s to authenticated, service_role', f.sig);
    elsif f.name like 'svc\_%' then
      execute format('grant execute on function %s to service_role', f.sig);
    end if;
  end loop;
end $$;

-- Storage policies (logos) call this, so signed-in users may run it; it only answers yes/no.
grant execute on function public._is_admin() to authenticated;

-- No direct table access for clients. Realtime needs to read the version counters only.
revoke all on all tables in schema public from anon, authenticated;
revoke all on all sequences in schema public from anon, authenticated;
grant select on public.live_pings to anon, authenticated;


-- ═════════ supabase_only.sql ═════════
-- Mamar Booking · Supabase-only setup. Paste AFTER the migrations (see platform/README.md).
-- Not run locally: Realtime, Storage and pg_cron exist only on Supabase.

-- Live updates: Realtime streams changes to the version counters (no personal data in this table).
do $$
begin
  if not exists (select 1 from pg_publication_tables where pubname = 'supabase_realtime' and tablename = 'live_pings') then
    alter publication supabase_realtime add table public.live_pings;
  end if;
end $$;

-- Logos: a public bucket anyone can read; only admins can upload or replace.
insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values ('logos', 'logos', true, 2097152, array['image/png','image/jpeg','image/webp','image/svg+xml'])
on conflict (id) do nothing;

drop policy if exists "logos read" on storage.objects;
create policy "logos read" on storage.objects for select to anon, authenticated using (bucket_id = 'logos');
drop policy if exists "logos admin write" on storage.objects;
create policy "logos admin write" on storage.objects for insert to authenticated with check (bucket_id = 'logos' and public._is_admin());
drop policy if exists "logos admin update" on storage.objects;
create policy "logos admin update" on storage.objects for update to authenticated using (bucket_id = 'logos' and public._is_admin());
drop policy if exists "logos admin delete" on storage.objects;
create policy "logos admin delete" on storage.objects for delete to authenticated using (bucket_id = 'logos' and public._is_admin());

-- Release unpaid holds every 5 minutes (they are also released lazily on every booking).
-- Needs the pg_cron extension: Dashboard → Database → Extensions → pg_cron → enable, then run:
-- select cron.schedule('mamar-expire-holds', '*/5 * * * *', $$select public.svc_expire_holds('{}')$$);

-- Make yourself the admin (after creating your user in Authentication → Users):
-- insert into public.admins (user_id) select id from auth.users where email = 'you@example.com';

-- Notifications → the `notify` Edge Function, straight from the database (pg_net), signed with a
-- secret the database generated itself (app_secrets.hook_secret). No webhook form, no typed keys.
-- Needs one row telling it where the functions live:
--   insert into public.app_secrets (key, value) values ('functions_url', 'https://<project-ref>.supabase.co/functions/v1')
--   on conflict (key) do update set value = excluded.value;
create extension if not exists pg_net with schema extensions;

create or replace function public._notify_http_trg() returns trigger
language plpgsql security definer set search_path = public, extensions as $$
declare
  base text := (select value from public.app_secrets where key = 'functions_url');
begin
  if base is null then return null; end if;
  perform net.http_post(
    url := base || '/notify',
    body := jsonb_build_object('record', jsonb_build_object('id', new.id)),
    headers := jsonb_build_object('Content-Type', 'application/json',
                                  'x-hook-secret', (select value from public.app_secrets where key = 'hook_secret')));
  return null;
end $$;

drop trigger if exists notifications_http on public.notifications;
create trigger notifications_http after insert on public.notifications
  for each row execute function public._notify_http_trg();
revoke all on function public._notify_http_trg() from public, anon, authenticated;

-- Who may become admin by signing in with an email link (run with the real address, not in the repo):
--   insert into public.admin_emails (email) values ('you@example.com') on conflict do nothing;
